101	
102	/* ── Schedule grid slot ── */
103	.schedule-slot {
104	  background: var(--color-schedule-slot-bg);
105	  border: 1px solid var(--color-schedule-slot-border);
106	  border-radius: var(--radius-sm);
107	  color: var(--color-schedule-slot-text);
108	  font-size: 0.6875rem;
109	  font-weight: 500;
110	  transition: background 100ms ease-out, border-color 100ms ease-out;
111	  cursor: pointer;
112	  user-select: none;
113	}
114	.schedule-slot:hover {
115	  background: oklch(62% 0.24 292 / 0.25);
116	  border-color: oklch(62% 0.24 292 / 0.7);
117	}
118	.schedule-slot[data-dragging="true"] {
119	  opacity: 0.7;
120	  background: var(--color-schedule-slot-drag);
121	}
122	
123	/* ── Schedule time-off overlay on grid ── */
124	.schedule-time-off {
125	  background: var(--color-schedule-time-off-bg);
126	  border: 1px solid var(--color-schedule-time-off-border);
127	  border-radius: var(--radius-sm);
128	}
129	.schedule-blocked {
130	  background: var(--color-schedule-blocked-bg);
131	  border: 1px solid var(--color-schedule-blocked-border);
132	  border-radius: var(--radius-sm);
133	}
134	
135	/* ── Permissions matrix ── */
136	.perm-check { color: var(--color-perm-check); }
137	.perm-cross { color: var(--color-perm-cross); }
138	.perm-group-row { background: var(--color-perm-group-header); }
139	
140	/* ── Calendar color swatch dot ── */
141	.cal-color-dot {
142	  display: inline-block;
143	  width: 10px;
144	  height: 10px;
145	  border-radius: 50%;
146	  flex-shrink: 0;
147	}
148	
149	/* ── Invite accept page ── */
150	.invite-accept-page {
151	  background: oklch(6% 0.01 264);
152	  min-height: 100dvh;
153	}
154	.invite-accept-card {
155	  background: oklch(10% 0.015 264);
156	  border: 1px solid oklch(22% 0.025 264);
157	}
