'use client'

import { cn } from '@/lib/utils'
import { Tooltip, TooltipContent, TooltipTrigger } from '@/components/ui/tooltip'

export const CALENDAR_SWATCHES = [
  { name: 'Ink Black',    hex: '#1a1a2e' },
  { name: 'Storm Blue',   hex: '#3b82f6' },
  { name: 'Neon Purple',  hex: '#a855f7' },
  { name: 'Rose Gold',    hex: '#fb7185' },
  { name: 'Forest Green', hex: '#22c55e' },
  { name: 'Amber Glow',   hex: '#f59e0b' },
  { name: 'Coral Red',    hex: '#ef4444' },
  { name: 'Teal Mist',    hex: '#14b8a6' },
  { name: 'Lavender',     hex: '#c084fc' },
  { name: 'Gold Foil',    hex: '#eab308' },
] as const

export type CalendarHex = (typeof CALENDAR_SWATCHES)[number]['hex']

interface CalendarColorPickerProps {
  value: string | null
  onChange: (hex: string) => void
  disabled?: boolean
}

export function CalendarColorPicker({ value, onChange, disabled }: CalendarColorPickerProps) {
  return (
    <div className="grid grid-cols-5 gap-2" role="radiogroup" aria-label="Calendar color">
      {CALENDAR_SWATCHES.map((swatch) => {
        const selected = value === swatch.hex
        return (
          <Tooltip key={swatch.hex}>
            <TooltipTrigger asChild>
              <button
                type="button"
                role="radio"
                aria-checked={selected}
                aria-label={swatch.name}
                disabled={disabled}
                onClick={() => onChange(swatch.hex)}
                className={cn(
                  'h-7 w-7 rounded-full transition-all duration-100 focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring',
                  selected && 'ring-2 ring-offset-2 ring-offset-background',
                  disabled && 'cursor-not-allowed opacity-50',
                )}
                style={{
                  backgroundColor: swatch.hex,
                  // Dynamic ring color matching swatch
                  ...(selected ? { '--tw-ring-color': swatch.hex } as React.CSSProperties : {}),
                }}
              />
            </TooltipTrigger>
            <TooltipContent side="bottom" className="text-xs">
              {swatch.name}
            </TooltipContent>
          </Tooltip>
        )
      })}
    </div>
  )
}

'use client'

import Link from 'next/link'
import { Avatar, AvatarFallback, AvatarImage } from '@/components/ui/avatar'
import { Badge } from '@/components/ui/badge'
import { cn } from '@/lib/utils'

export interface ArtistCardData {
  id: string
  display_name: string
  avatar_url: string | null
  calendar_color: string | null
  status: 'active' | 'on_leave' | 'archived'
  role?: string | null
  specialties: string[]
  booking_count_this_month: number
  commission_default_pct: number
}

interface ArtistCardProps {
  artist: ArtistCardData
}

const STATUS_CLASS: Record<string, string> = {
  active:    'badge-artist-active',
  on_leave:  'badge-artist-on-leave',
  archived:  'badge-artist-archived',
}

const STATUS_LABEL: Record<string, string> = {
  active:    'Active',
  on_leave:  'On Leave',
  archived:  'Archived',
}

const ROLE_CLASS: Record<string, string> = {
  owner:        'chip-role-owner',
  admin:        'chip-role-admin',
  artist:       'chip-role-artist',
  receptionist: 'chip-role-receptionist',
  guest_artist: 'chip-role-guest-artist',
}

const ROLE_LABEL: Record<string, string> = {
  owner:        'Owner',
  admin:        'Admin',
  artist:       'Artist',
  receptionist: 'Receptionist',
  guest_artist: 'Guest Artist',
}

function getInitials(name: string): string {
  return name
    .split(' ')
    .map((n) => n[0])
    .slice(0, 2)
    .join('')
    .toUpperCase()
}

export function ArtistCard({ artist }: ArtistCardProps) {
  const visibleSpecialties = artist.specialties.slice(0, 2)
  const extraCount = artist.specialties.length - 2

  return (
    <Link href={`/artists/${artist.id}`} className="block focus-visible:outline-none">
      <div
        className={cn(
          'group relative cursor-pointer rounded-xl border border-border bg-card p-4 shadow-soft',
          'kpi-card-hover hover:border-primary/30',
          'flex flex-col gap-3',
        )}
      >
        {/* Avatar + color dot */}
        <div className="relative w-fit">
          <Avatar className="h-12 w-12 rounded-full">
            <AvatarImage src={artist.avatar_url ?? undefined} alt={artist.display_name} />
            <AvatarFallback className="bg-muted text-muted-foreground text-sm font-medium">
              {getInitials(artist.display_name)}
            </AvatarFallback>
          </Avatar>
          {artist.calendar_color && (
            <span
              className="cal-color-dot absolute -top-0.5 -right-0.5 ring-2 ring-background"
              style={{ backgroundColor: artist.calendar_color }}
              aria-hidden="true"
            />
          )}
        </div>

        {/* Name */}
        <p className="text-sm font-semibold leading-tight">{artist.display_name}</p>

        {/* Role + Status chips */}
        <div className="flex flex-wrap gap-1.5">
          {artist.role && ROLE_CLASS[artist.role] && (
            <span
              className={cn(
                'inline-flex h-5 items-center rounded-full px-2 text-[10px] font-medium',
                ROLE_CLASS[artist.role],
              )}
            >
              {ROLE_LABEL[artist.role] ?? artist.role}
            </span>
          )}
          <span
            className={cn(
              'inline-flex h-5 items-center rounded-full px-2 text-[10px] font-medium',
              STATUS_CLASS[artist.status] ?? 'badge-artist-archived',
            )}
          >
            {STATUS_LABEL[artist.status] ?? artist.status}
          </span>
        </div>

        {/* Specialties */}
        {artist.specialties.length > 0 && (
          <div className="flex flex-wrap gap-1">
            {visibleSpecialties.map((s) => (
              <Badge key={s} variant="outline" className="h-4 text-[10px] text-muted-foreground px-1.5">
                {s}
              </Badge>
            ))}
            {extraCount > 0 && (
              <Badge variant="outline" className="h-4 text-[10px] text-muted-foreground px-1.5">
                +{extraCount} more
              </Badge>
            )}
          </div>
        )}

        {/* Stats */}
        <div className="flex items-center justify-between text-xs text-muted-foreground tabular-nums mt-auto">
          <span>{artist.booking_count_this_month} bookings/mo</span>
          <span>{artist.commission_default_pct}% commission</span>
        </div>
      </div>
    </Link>
  )
}

