'use client'

import { useState, useEffect, useMemo } from 'react'
import { useRouter } from 'next/navigation'
import { Skeleton } from '@/components/ui/skeleton'
import { Alert, AlertDescription } from '@/components/ui/alert'
import { Button } from '@/components/ui/button'
import { AlertCircle, RefreshCw, SearchX, Users } from 'lucide-react'
import { ArtistCard } from '@/components/artists/ArtistCard'
import { ArtistTable } from '@/components/artists/ArtistTable'
import { ArtistListHeader, type ArtistViewMode } from '@/components/artists/ArtistListHeader'
import { ArtistFilterBar, type ArtistFilters } from '@/components/artists/ArtistFilterBar'
import { InviteModal } from '@/components/settings/team/InviteModal'
import type { ArtistCardData } from '@/components/artists/ArtistCard'

const STORAGE_KEY = 'inkos:artists:view'

export default function ArtistsPage() {
  const router = useRouter()
  const [viewMode, setViewMode] = useState<ArtistViewMode>('grid')
  const [artists, setArtists] = useState<ArtistCardData[]>([])
  const [loading, setLoading] = useState(true)
  const [error, setError] = useState<string | null>(null)
  const [showInviteModal, setShowInviteModal] = useState(false)
  const [filters, setFilters] = useState<ArtistFilters>({
    status: 'all',
    specialty: 'all',
    role: 'all',
  })

  // Persist view mode to localStorage
  useEffect(() => {
    const stored = localStorage.getItem(STORAGE_KEY)
    if (stored === 'grid' || stored === 'table') setViewMode(stored)
  }, [])

  const handleViewModeChange = (mode: ArtistViewMode) => {
    setViewMode(mode)
    localStorage.setItem(STORAGE_KEY, mode)
  }

  const fetchArtists = async () => {
    setLoading(true)
    setError(null)
    try {
      const res = await fetch('/api/artists')
      if (!res.ok) throw new Error('Failed to fetch artists')
      const json = await res.json() as { data: ArtistCardData[] }
      setArtists(json.data ?? [])
    } catch {
      setError('Could not load artists. Please try again.')
    } finally {
      setLoading(false)
    }
  }

  useEffect(() => {
    void fetchArtists()
  }, [])

  // All unique specialties across all artists
  const allSpecialties = useMemo(() => {
    const set = new Set<string>()
    artists.forEach((a) => a.specialties.forEach((s) => set.add(s)))
    return [...set].sort()
  }, [artists])

  // Client-side filtering
  const filtered = useMemo(() => {
    return artists.filter((a) => {
      if (filters.status !== 'all' && a.status !== filters.status) return false
      if (filters.specialty !== 'all' && !a.specialties.includes(filters.specialty)) return false
      if (filters.role !== 'all' && a.role !== filters.role) return false
      return true
    })
  }, [artists, filters])

  const hasActiveFilters =
    filters.status !== 'all' || filters.specialty !== 'all' || filters.role !== 'all'

  const clearFilters = () =>
    setFilters({ status: 'all', specialty: 'all', role: 'all' })

  return (
    <div className="flex flex-col min-h-0">
      <ArtistListHeader
        viewMode={viewMode}
        onViewModeChange={handleViewModeChange}
        onAddArtist={() => router.push('/artists/new')}
        onInviteArtist={() => setShowInviteModal(true)}
      />

      <ArtistFilterBar
        filters={filters}
        onFiltersChange={setFilters}
        totalCount={artists.length}
        filteredCount={filtered.length}
        specialties={allSpecialties}
      />

      <div className="flex-1 p-6">
        {/* Error state */}
        {error && !loading && (
          <Alert variant="destructive" className="mb-6">
            <AlertCircle className="h-4 w-4" />
            <AlertDescription className="flex items-center justify-between">
              <span>{error}</span>
              <Button
                variant="ghost"
                size="sm"
                onClick={() => void fetchArtists()}
                className="ml-4 h-7 gap-1.5"
              >
                <RefreshCw className="h-3.5 w-3.5" />
                Retry
              </Button>
            </AlertDescription>
          </Alert>
        )}

        {/* Loading state */}
        {loading && (
          <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 xl:grid-cols-4 gap-4">
            {Array.from({ length: 8 }).map((_, i) => (
              <Skeleton key={i} className="h-[168px] rounded-xl" />
            ))}
          </div>
        )}

        {/* No artists at all */}
        {!loading && !error && artists.length === 0 && (
          <div className="flex flex-col items-center gap-3 py-16 px-4">
            <Users className="h-10 w-10 text-muted-foreground/40" />
            <p className="text-sm font-semibold">No artists yet</p>
            <p className="text-sm text-muted-foreground text-center max-w-xs">
              Add your first artist or invite them to join your studio.
            </p>
            <div className="flex items-center gap-2 mt-1">
              <Button size="sm" onClick={() => router.push('/artists/new')}>
                + Add Artist
              </Button>
              <Button size="sm" variant="outline" onClick={() => setShowInviteModal(true)}>
                Invite Artist
              </Button>
            </div>
          </div>
        )}

        {/* Filter no-results */}
        {!loading && !error && artists.length > 0 && filtered.length === 0 && hasActiveFilters && (
          <div className="flex flex-col items-center gap-3 py-16 px-4">
            <SearchX className="h-10 w-10 text-muted-foreground/40" />
            <p className="text-sm font-semibold">No artists match</p>
            <p className="text-sm text-muted-foreground text-center max-w-xs">
              Try a different status, specialty, or role filter.
            </p>
            <Button variant="ghost" size="sm" onClick={clearFilters}>
              Clear filters
            </Button>
          </div>
        )}

        {/* Grid view */}
        {!loading && !error && filtered.length > 0 && viewMode === 'grid' && (
          <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 xl:grid-cols-4 gap-4">
            {filtered.map((artist) => (
              <ArtistCard key={artist.id} artist={artist} />
            ))}
          </div>
        )}

        {/* Table view */}
        {!loading && !error && filtered.length > 0 && viewMode === 'table' && (
          <ArtistTable
            artists={filtered}
            canDeactivate={true}
            onDeactivate={(id) => {
              // Will be wired to real API in team settings item
              void id
            }}
          />
        )}
      </div>

      {/* Invite modal — pre-selects artist role */}
      {showInviteModal && (
        <InviteModal
          open={showInviteModal}
          onOpenChange={setShowInviteModal}
          defaultRole="artist"
          onSuccess={() => {
            setShowInviteModal(false)
            void fetchArtists()
          }}
        />
      )}
    </div>
  )
}

'use client'

import { use, useState, useEffect, useCallback } from 'react'
import { useRouter } from 'next/navigation'
import { Tabs, TabsContent, TabsList, TabsTrigger } from '@/components/ui/tabs'
import { Card, CardContent, CardHeader, CardTitle } from '@/components/ui/card'
import { Button } from '@/components/ui/button'
import { Input } from '@/components/ui/input'
import { Label } from '@/components/ui/label'
import { Textarea } from '@/components/ui/textarea'
import { Switch } from '@/components/ui/switch'
import { Badge } from '@/components/ui/badge'
import { Skeleton } from '@/components/ui/skeleton'
import {
  AlertDialog,
  AlertDialogAction,
  AlertDialogCancel,
  AlertDialogContent,
  AlertDialogDescription,
  AlertDialogFooter,
  AlertDialogHeader,
  AlertDialogTitle,
} from '@/components/ui/alert-dialog'
import { toast } from 'sonner'
import { Copy, Instagram, ExternalLink } from 'lucide-react'
import { formatDistanceToNow } from 'date-fns'
import { ArtistDetailHeader } from '@/components/artists/ArtistDetailHeader'
import { CalendarColorPicker } from '@/components/artists/CalendarColorPicker'
import { usePermissions } from '@/lib/team/permissions-context'
import type { Database } from '@/lib/supabase/types'

type Artist = Database['public']['Tables']['artists']['Row']
type Member = Database['public']['Tables']['studio_members']['Row']

interface ArtistDetailData extends Artist {
  member?: Pick<Member, 'role' | 'joined_at' | 'last_active_at' | 'invite_id'> & {
    inviter_name?: string | null
  }
}

const ROLE_CLASS: Record<string, string> = {
  owner:        'chip-role-owner',
  admin:        'chip-role-admin',
  artist:       'chip-role-artist',
  receptionist: 'chip-role-receptionist',
  guest_artist: 'chip-role-guest-artist',
}
const ROLE_LABEL: Record<string, string> = {
  owner:        'Owner',
  admin:        'Admin',
  artist:       'Artist',
  receptionist: 'Receptionist',
  guest_artist: 'Guest Artist',
}

// Specialties multi-select as chips
function SpecialtiesInput({
  value,
  onChange,
}: {
  value: string[]
  onChange: (v: string[]) => void
}) {
  const [input, setInput] = useState('')

  const addSpecialty = () => {
    const trimmed = input.trim()
    if (trimmed && !value.includes(trimmed)) {
      onChange([...value, trimmed])
    }
    setInput('')
  }

  const remove = (s: string) => onChange(value.filter((v) => v !== s))

  return (
    <div className="space-y-2">
      <div className="flex flex-wrap gap-1.5 min-h-[32px]">
        {value.map((s) => (
          <Badge
            key={s}
            variant="secondary"
            className="h-6 gap-1 cursor-pointer hover:bg-destructive/10"
            onClick={() => remove(s)}
          >
            {s}
            <span className="text-muted-foreground">×</span>
          </Badge>
        ))}
      </div>
      <div className="flex gap-2">
        <Input
          placeholder="Add specialty..."
          value={input}
          onChange={(e) => setInput(e.target.value)}
          onKeyDown={(e) => {
            if (e.key === 'Enter') {
              e.preventDefault()
              addSpecialty()
            }
          }}
          className="h-8 text-sm"
        />
        <Button type="button" size="sm" variant="outline" onClick={addSpecialty}>
          Add
        </Button>
      </div>
    </div>
  )
}

// Languages multi-select (same pattern)
function LanguagesInput({
  value,
  onChange,
}: {
  value: string[]
  onChange: (v: string[]) => void
}) {
  const [input, setInput] = useState('')

  const add = () => {
    const trimmed = input.trim()
    if (trimmed && !value.includes(trimmed)) onChange([...value, trimmed])
    setInput('')
  }

  const remove = (l: string) => onChange(value.filter((v) => v !== l))

  return (
    <div className="space-y-2">
      <div className="flex flex-wrap gap-1.5 min-h-[32px]">
        {value.map((l) => (
          <Badge
            key={l}
            variant="secondary"
            className="h-6 gap-1 cursor-pointer hover:bg-destructive/10"
            onClick={() => remove(l)}
          >
            {l}
            <span className="text-muted-foreground">×</span>
          </Badge>
        ))}
      </div>
      <div className="flex gap-2">
        <Input
          placeholder="Add language..."
          value={input}
          onChange={(e) => setInput(e.target.value)}
          onKeyDown={(e) => {
            if (e.key === 'Enter') {
              e.preventDefault()
              add()
            }
          }}
          className="h-8 text-sm"
        />
        <Button type="button" size="sm" variant="outline" onClick={add}>
          Add
        </Button>
      </div>
    </div>
  )
}

export default function ArtistDetailPage({
  params,
}: {
  params: Promise<{ id: string }>
}) {
  const { id } = use(params)
  const router = useRouter()
  const { canDo } = usePermissions()

  const [artist, setArtist] = useState<ArtistDetailData | null>(null)
  const [loading, setLoading] = useState(true)
  const [saving, setSaving] = useState(false)
  const [deactivateOpen, setDeactivateOpen] = useState(false)

  // Profile form state
  const [displayName, setDisplayName] = useState('')
  const [bio, setBio] = useState('')
  const [profileBioPublic, setProfileBioPublic] = useState('')
  const [specialties, setSpecialties] = useState<string[]>([])
  const [languages, setLanguages] = useState<string[]>([])
  const [instagram, setInstagram] = useState('')
  const [portfolio, setPortfolio] = useState('')
  const [calendarColor, setCalendarColor] = useState<string | null>(null)
  const [hourlyRateCents, setHourlyRateCents] = useState<string>('')
  const [maxBookingsPerDay, setMaxBookingsPerDay] = useState<string>('')
  const [acceptsWalkIns, setAcceptsWalkIns] = useState(false)
  const [minAgeCutOff, setMinAgeCutOff] = useState<string>('')
  const [commissionPct, setCommissionPct] = useState<string>('')

  const fetchArtist = useCallback(async () => {
    setLoading(true)
    try {
      const res = await fetch(`/api/artists/${id}`)
      if (!res.ok) throw new Error('Not found')
      const json = await res.json() as { data: ArtistDetailData }
      const a = json.data
      setArtist(a)
      setDisplayName(a.display_name)
      setBio(a.bio ?? '')
      setProfileBioPublic(a.profile_bio_public ?? '')
      setSpecialties(a.specialties ?? [])
      setLanguages(a.languages_spoken ?? [])
      setInstagram(a.social_instagram ?? '')
      setPortfolio(a.social_portfolio ?? '')
      setCalendarColor(a.calendar_color)
      setHourlyRateCents(a.hourly_rate_cents != null ? String(a.hourly_rate_cents / 100) : '')
      setMaxBookingsPerDay(a.max_bookings_per_day != null ? String(a.max_bookings_per_day) : '')
      setAcceptsWalkIns(a.accepts_walk_ins)
      setMinAgeCutOff(a.min_age_cut_off != null ? String(a.min_age_cut_off) : '')
      setCommissionPct(String(a.commission_default_pct))
    } catch {
      toast.error('Could not load artist profile')
    } finally {
      setLoading(false)
    }
  }, [id])

  useEffect(() => { void fetchArtist() }, [fetchArtist])

  const handleSave = async () => {
    setSaving(true)
    try {
      const res = await fetch(`/api/artists/${id}`, {
        method: 'PATCH',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          display_name: displayName,
          bio: bio || null,
          profile_bio_public: profileBioPublic || null,
          specialties,
          languages_spoken: languages,
          social_instagram: instagram || null,
          social_portfolio: portfolio || null,
          calendar_color: calendarColor,
          hourly_rate_cents: hourlyRateCents ? Math.round(parseFloat(hourlyRateCents) * 100) : null,
          max_bookings_per_day: maxBookingsPerDay ? parseInt(maxBookingsPerDay, 10) : null,
          accepts_walk_ins: acceptsWalkIns,
          min_age_cut_off: minAgeCutOff ? parseInt(minAgeCutOff, 10) : null,
          commission_default_pct: parseFloat(commissionPct) || 0,
        }),
      })
      if (!res.ok) throw new Error('Save failed')
      toast.success('Profile saved')
      void fetchArtist()
    } catch {
      toast.error('Failed to save profile')
    } finally {
      setSaving(false)
    }
  }

  const handleDeactivate = async () => {
    try {
      const res = await fetch(`/api/studio-members/${id}`, {
        method: 'DELETE',
      })
      if (!res.ok) throw new Error('Deactivate failed')
      toast(`${artist?.display_name ?? 'Member'} has been deactivated`, { duration: 6000 })
      router.push('/artists')
    } catch {
      toast.error('Failed to deactivate')
    }
  }

  if (loading) {
    return (
      <div className="flex flex-col">
        <div className="flex items-center gap-4 px-6 py-4 border-b border-border/50">
          <Skeleton className="h-4 w-24" />
          <Skeleton className="h-8 w-8 rounded-full" />
          <Skeleton className="h-5 w-40" />
        </div>
        <div className="p-6 space-y-4">
          <Skeleton className="h-10 w-full max-w-xl" />
          <Skeleton className="h-32 w-full max-w-xl" />
        </div>
      </div>
    )
  }

  if (!artist) {
    return (
      <div className="p-6 text-sm text-muted-foreground">
        Artist not found.
      </div>
    )
  }

  const role = artist.member?.role ?? null
  const isOwner = canDo('admin.change_roles')

  return (
    <div className="flex flex-col min-h-0">
      <ArtistDetailHeader
        id={id}
        displayName={artist.display_name}
        avatarUrl={artist.avatar_url}
        calendarColor={artist.calendar_color}
        status={artist.status}
        role={role}
        canDeactivate={isOwner}
        onDeactivate={() => setDeactivateOpen(true)}
      />

      <Tabs defaultValue="profile" className="mt-0 flex-1">
        <TabsList className="w-full justify-start border-b rounded-none bg-transparent h-auto px-6 gap-0">
          {['profile', 'schedule', 'performance', 'team'].map((tab) => (
            <TabsTrigger
              key={tab}
              value={tab}
              className="rounded-none border-b-2 border-transparent data-[state=active]:border-primary px-4 pb-3 pt-0 text-sm font-medium capitalize"
            >
              {tab}
            </TabsTrigger>
          ))}
        </TabsList>

        {/* ── Profile Tab ── */}
        <TabsContent value="profile" className="mt-0">
          <div className="grid grid-cols-1 lg:grid-cols-3 gap-6 p-6">
            {/* Left column */}
            <div className="lg:col-span-2 space-y-6">
              {/* Identity */}
              <Card className="shadow-soft">
                <CardHeader className="pb-4">
                  <CardTitle className="text-base font-semibold">Identity</CardTitle>
                </CardHeader>
                <CardContent className="space-y-4">
                  <div className="space-y-1.5">
                    <Label className="text-sm">Display name</Label>
                    <Input
                      value={displayName}
                      onChange={(e) => setDisplayName(e.target.value)}
                      placeholder="Artist display name"
                    />
                  </div>
                  <div className="space-y-1.5">
                    <Label className="text-sm">Bio</Label>
                    <Textarea
                      value={bio}
                      onChange={(e) => setBio(e.target.value)}
                      rows={4}
                      maxLength={500}
                      placeholder="About this artist..."
                    />
                    <p className="text-xs text-muted-foreground text-right">{bio.length}/500</p>
                  </div>
                  <div className="space-y-1.5">
                    <Label className="text-sm">
                      Public bio{' '}
                      <span className="text-xs text-muted-foreground">(shown on booking page)</span>
                    </Label>
                    <Textarea
                      value={profileBioPublic}
                      onChange={(e) => setProfileBioPublic(e.target.value)}
                      rows={3}
                      placeholder="Short public description..."
                    />
                  </div>
                </CardContent>
              </Card>

              {/* Specialties */}
              <Card className="shadow-soft">
                <CardHeader className="pb-4">
                  <CardTitle className="text-base font-semibold">Specialties</CardTitle>
                </CardHeader>
                <CardContent>
                  <SpecialtiesInput value={specialties} onChange={setSpecialties} />
                </CardContent>
              </Card>

              {/* Social & Portfolio */}
              <Card className="shadow-soft">
                <CardHeader className="pb-4">
                  <CardTitle className="text-base font-semibold">Social & Portfolio</CardTitle>
                </CardHeader>
                <CardContent className="space-y-4">
                  <div className="space-y-1.5">
                    <Label className="text-sm">Instagram</Label>
                    <div className="relative">
                      <Instagram className="absolute left-2.5 top-2.5 h-4 w-4 text-muted-foreground" />
                      <Input
                        value={instagram}
                        onChange={(e) => setInstagram(e.target.value)}
                        placeholder="@instagram_handle"
                        className="pl-8"
                      />
                    </div>
                  </div>
                  <div className="space-y-1.5">
                    <Label className="text-sm">Portfolio URL</Label>
                    <div className="relative">
                      <ExternalLink className="absolute left-2.5 top-2.5 h-4 w-4 text-muted-foreground" />
                      <Input
                        value={portfolio}
                        onChange={(e) => setPortfolio(e.target.value)}
                        placeholder="https://portfolio.com"
                        className="pl-8"
                      />
                    </div>
                  </div>
                </CardContent>
              </Card>
            </div>

            {/* Right column */}
            <div className="space-y-6">
              {/* Calendar & Availability */}
              <Card className="shadow-soft">
                <CardHeader className="pb-4">
                  <CardTitle className="text-base font-semibold">Calendar & Availability</CardTitle>
                </CardHeader>
                <CardContent className="space-y-5">
                  <div className="space-y-2">
                    <Label className="text-sm">Calendar color</Label>
                    <CalendarColorPicker value={calendarColor} onChange={setCalendarColor} />
                  </div>

                  <div className="space-y-1.5">
                    <Label className="text-sm">Hourly rate</Label>
                    <div className="relative">
                      <span className="absolute left-2.5 top-2.5 text-sm text-muted-foreground">$</span>
                      <Input
                        type="number"
                        min={0}
                        step={0.01}
                        value={hourlyRateCents}
                        onChange={(e) => setHourlyRateCents(e.target.value)}
                        placeholder="0.00"
                        className="pl-6"
                      />
                    </div>
                  </div>

                  <div className="space-y-1.5">
                    <Label className="text-sm">Max bookings per day</Label>
                    <Input
                      type="number"
                      min={1}
                      max={99}
                      value={maxBookingsPerDay}
