                    variant="outline"
                    className="text-destructive border-destructive/30 hover:bg-destructive/5"
                    onClick={() => setDeactivateOpen(true)}
                  >
                    Deactivate Member
                  </Button>
                </div>
              )}
            </CardContent>
          </Card>
        </TabsContent>
      </Tabs>

      {/* Deactivate confirmation */}
      <AlertDialog open={deactivateOpen} onOpenChange={setDeactivateOpen}>
        <AlertDialogContent>
          <AlertDialogHeader>
            <AlertDialogTitle>Deactivate {artist.display_name}?</AlertDialogTitle>
            <AlertDialogDescription>
              They will lose access to the studio immediately. Their bookings and records are retained.
            </AlertDialogDescription>
          </AlertDialogHeader>
          <AlertDialogFooter>
            <AlertDialogCancel>Cancel</AlertDialogCancel>
            <AlertDialogAction
              className="bg-destructive text-destructive-foreground hover:bg-destructive/90"
              onClick={() => void handleDeactivate()}
            >
              Deactivate
            </AlertDialogAction>
          </AlertDialogFooter>
        </AlertDialogContent>
      </AlertDialog>
    </div>
  )
}

import type { NextRequest } from 'next/server'
import { NextResponse } from 'next/server'
import { z } from 'zod'
import { createClient, getAuthenticatedUser } from '@/lib/supabase/server'
import { authedRatelimit } from '@/lib/rate-limit'
import { logger } from '@/lib/logger'
import { updateLastActive } from '@/lib/team/last-active'

const UpdateArtistSchema = z.object({
  display_name: z.string().min(1).max(100).optional(),
  bio: z.string().max(500).nullable().optional(),
  profile_bio_public: z.string().max(500).nullable().optional(),
  specialties: z.array(z.string().max(50)).max(20).optional(),
  languages_spoken: z.array(z.string().max(50)).max(10).nullable().optional(),
  social_instagram: z.string().max(100).nullable().optional(),
  social_portfolio: z.string().max(200).url({ message: 'Must be a valid URL' }).nullable().optional(),
  calendar_color: z.string().regex(/^#[0-9a-fA-F]{6}$/).nullable().optional(),
  hourly_rate_cents: z.number().int().min(0).nullable().optional(),
  max_bookings_per_day: z.number().int().min(1).max(99).nullable().optional(),
  accepts_walk_ins: z.boolean().optional(),
  min_age_cut_off: z.number().int().min(0).max(99).nullable().optional(),
  commission_default_pct: z.number().min(0).max(100).optional(),
  status: z.enum(['active', 'on_leave', 'archived']).optional(),
})

export async function GET(
  _request: NextRequest,
  { params }: { params: Promise<{ id: string }> },
) {
  const authUser = await getAuthenticatedUser()
  if (!authUser) {
    return NextResponse.json({ error: 'Unauthorized' }, { status: 401 })
  }

  const { success } = await authedRatelimit.limit(authUser.user.id)
  if (!success) {
    return NextResponse.json({ error: 'Too many requests' }, { status: 429 })
  }

  const { id } = await params

  try {
    const supabase = await createClient()

    const { data: artist, error } = await supabase
      .from('artists')
      .select(`
        id, studio_id, profile_id, display_name, bio, portfolio_url, avatar_url,
        specialties, commission_default_pct, status, sort_order,
        calendar_color, hourly_rate_cents, min_age_cut_off, accepts_walk_ins,
        max_bookings_per_day, profile_bio_public, languages_spoken,
        social_instagram, social_portfolio, last_active_at, created_at, updated_at
      `)
      .eq('id', id)
      .eq('studio_id', authUser.studioId)
      .single()

    if (error || !artist) {
      return NextResponse.json({ error: 'Artist not found' }, { status: 404 })
    }

    // Fetch studio membership info for the artist's profile_id
    let member = null
    if (artist.profile_id) {
      const { data: memberData } = await supabase
        .from('studio_members')
        .select('role, joined_at, last_active_at, invite_id')
        .eq('studio_id', authUser.studioId)
        .eq('user_id', artist.profile_id)
        .is('deactivated_at', null)
        .maybeSingle()

      if (memberData) {
        // Get inviter name if there's an invite
        let inviterName: string | null = null
        if (memberData.invite_id) {
          const { data: invite } = await supabase
            .from('team_invites')
            .select('invited_by, profiles:invited_by(full_name)')
            .eq('id', memberData.invite_id)
            .single()
          inviterName = (invite?.profiles as { full_name: string | null } | null)?.full_name ?? null
        }
        member = { ...memberData, inviter_name: inviterName }
      }
    }

    return NextResponse.json({ data: { ...artist, member } })
  } catch (err) {
    logger.error({ err }, 'artist GET unexpected error')
    return NextResponse.json({ error: 'Internal server error' }, { status: 500 })
  }
}

export async function PATCH(
  request: NextRequest,
  { params }: { params: Promise<{ id: string }> },
) {
  const authUser = await getAuthenticatedUser()
  if (!authUser) {
    return NextResponse.json({ error: 'Unauthorized' }, { status: 401 })
  }

  const { success } = await authedRatelimit.limit(authUser.user.id)
  if (!success) {
    return NextResponse.json({ error: 'Too many requests' }, { status: 429 })
  }

  const { id } = await params

  const body = UpdateArtistSchema.safeParse(await request.json())
  if (!body.success) {
    return NextResponse.json({ error: body.error.flatten() }, { status: 400 })
  }

  try {
    const supabase = await createClient()

    // Verify ownership — artist must belong to user's studio
    const { data: existing } = await supabase
      .from('artists')
      .select('id, studio_id')
      .eq('id', id)
      .eq('studio_id', authUser.studioId)
      .single()

    if (!existing) {
      return NextResponse.json({ error: 'Artist not found' }, { status: 404 })
    }

    // commission_default_pct update: owner check
    const updateData = { ...body.data }
    if (updateData.commission_default_pct !== undefined) {
      // Check if user is owner/admin — only they can change commission
      const { data: member } = await supabase
        .from('studio_members')
        .select('role')
        .eq('studio_id', authUser.studioId)
        .eq('user_id', authUser.user.id)
        .is('deactivated_at', null)
        .single()

      if (member?.role !== 'owner' && member?.role !== 'admin') {
        delete updateData.commission_default_pct
      }
    }

    const { data, error } = await supabase
      .from('artists')
      .update({ ...updateData, updated_at: new Date().toISOString() })
      .eq('id', id)
      .eq('studio_id', authUser.studioId)
      .select()
      .single()

    if (error) {
      logger.error({ err: error, artistId: id }, 'artist PATCH failed')
      return NextResponse.json({ error: 'Failed to update artist' }, { status: 500 })
    }

    await updateLastActive(authUser.studioId)

    return NextResponse.json({ data })
  } catch (err) {
    logger.error({ err }, 'artist PATCH unexpected error')
    return NextResponse.json({ error: 'Internal server error' }, { status: 500 })
  }
}

