'use client'

import { useState } from 'react'
import {
  Dialog,
  DialogContent,
  DialogHeader,
  DialogTitle,
} from '@/components/ui/dialog'
import { Button } from '@/components/ui/button'
import { Input } from '@/components/ui/input'
import { Label } from '@/components/ui/label'
import { Textarea } from '@/components/ui/textarea'
import { RadioGroup, RadioGroupItem } from '@/components/ui/radio-group'
import { toast } from 'sonner'
import { Crown, Shield, Palette, Phone, UserPlus, Loader2 } from 'lucide-react'
import { cn } from '@/lib/utils'
import { usePermissions } from '@/lib/team/permissions-context'

type Role = 'admin' | 'artist' | 'receptionist' | 'guest_artist' | 'owner'

const ROLES: {
  value: Role
  label: string
  description: string
  icon: React.ComponentType<{ className?: string }>
  ownerOnly?: boolean
}[] = [
  {
    value: 'owner',
    label: 'Owner',
    description: 'Full studio control. Billing, deletion, role management.',
    icon: Crown,
    ownerOnly: true,
  },
  {
    value: 'admin',
    label: 'Admin',
    description: 'Manage bookings, artists, clients. No billing or studio delete.',
    icon: Shield,
  },
  {
    value: 'artist',
    label: 'Artist',
    description: 'Manage own bookings, schedule, and clients.',
    icon: Palette,
  },
  {
    value: 'receptionist',
    label: 'Receptionist',
    description: 'Book and manage all appointments. No payroll access.',
    icon: Phone,
  },
  {
    value: 'guest_artist',
    label: 'Guest Artist',
    description: 'Limited access to own bookings and schedule only.',
    icon: UserPlus,
  },
]

interface InviteModalProps {
  open: boolean
  onOpenChange: (open: boolean) => void
  defaultRole?: Role
  onSuccess?: () => void
}

export function InviteModal({ open, onOpenChange, defaultRole = 'artist', onSuccess }: InviteModalProps) {
  const { canDo } = usePermissions()
  const isOwner = canDo('admin.change_roles')

  const [email, setEmail] = useState('')
  const [role, setRole] = useState<Role>(defaultRole)
  const [commissionPct, setCommissionPct] = useState('30')
  const [personalMessage, setPersonalMessage] = useState('')
  const [emailError, setEmailError] = useState('')
  const [sending, setSending] = useState(false)

  const visibleRoles = ROLES.filter((r) => !r.ownerOnly || isOwner)

  const validateEmail = (value: string): boolean => {
    const re = /^[^\s@]+@[^\s@]+\.[^\s@]+$/
    if (!value.trim()) {
      setEmailError('Email is required')
      return false
    }
    if (!re.test(value.trim())) {
      setEmailError('Enter a valid email address')
      return false
    }
    setEmailError('')
    return true
  }

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault()
    if (!validateEmail(email)) return

    setSending(true)
    try {
      const payload: Record<string, unknown> = {
        email: email.trim().toLowerCase(),
        role,
        personal_message: personalMessage.trim() || null,
      }
      if (role === 'artist') {
        payload.commission_pct = parseFloat(commissionPct) || 0
      }

      const res = await fetch('/api/team-invites', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify(payload),
      })

      const json = await res.json() as { error?: string }

      if (!res.ok) {
        if (json.error === 'already_a_member') {
          toast.error('This person is already a member.')
        } else if (json.error === 'invalid_email') {
          setEmailError('This email address is not valid.')
        } else {
          toast.error(json.error ?? 'Failed to send invite')
        }
        return
      }

      toast.success(`Invite sent to ${email.trim()}`)
      setEmail('')
      setPersonalMessage('')
      setCommissionPct('30')
      setRole(defaultRole)
      onSuccess?.()
      onOpenChange(false)
    } catch {
      toast.error('Failed to send invite')
    } finally {
      setSending(false)
    }
  }

  return (
    <Dialog open={open} onOpenChange={onOpenChange}>
      <DialogContent className="max-w-md">
        <DialogHeader>
          <DialogTitle>Invite a Team Member</DialogTitle>
        </DialogHeader>

        <form onSubmit={(e) => void handleSubmit(e)} className="space-y-5">
          {/* Email */}
          <div className="space-y-1.5">
            <Label>Email address <span className="text-destructive">*</span></Label>
            <Input
              type="email"
              placeholder="colleague@example.com"
              value={email}
              onChange={(e) => {
                setEmail(e.target.value)
                if (emailError) setEmailError('')
              }}
              onBlur={() => validateEmail(email)}
              aria-invalid={!!emailError}
              aria-describedby={emailError ? 'email-error' : undefined}
            />
            {emailError && (
              <p id="email-error" role="alert" className="text-xs text-destructive">
                {emailError}
              </p>
            )}
          </div>

          {/* Role picker */}
          <div className="space-y-1.5">
            <Label>Role <span className="text-destructive">*</span></Label>
            <RadioGroup
              value={role}
              onValueChange={(v) => setRole(v as Role)}
              className="space-y-1.5"
            >
              {visibleRoles.map((r) => {
                const Icon = r.icon
                const selected = role === r.value
                return (
                  <label
                    key={r.value}
                    className={cn(
                      'flex items-start gap-3 p-3 rounded-lg border cursor-pointer transition-colors duration-150',
                      selected
                        ? 'border-primary/50 bg-primary/[0.06]'
                        : 'border-border/50 hover:border-border',
                    )}
                  >
                    <RadioGroupItem value={r.value} className="mt-0.5" />
                    <div className="flex-1 min-w-0">
                      <div className="flex items-center gap-2">
                        <Icon className="h-4 w-4 text-muted-foreground" />
                        <p className="text-sm font-semibold capitalize">{r.label}</p>
                      </div>
                      <p className="text-xs text-muted-foreground mt-0.5">{r.description}</p>
                    </div>
                  </label>
                )
              })}
            </RadioGroup>
          </div>

          {/* Artist-conditional fields */}
          {role === 'artist' && (
            <div className="space-y-4 animate-in fade-in-0 slide-in-from-top-1 duration-150">
              <div className="space-y-1.5">
                <Label className="text-sm">Commission %</Label>
                <div className="flex items-center gap-2">
                  <Input
                    type="number"
                    min={0}
                    max={100}
                    className="w-20"
                    value={commissionPct}
                    onChange={(e) => setCommissionPct(e.target.value)}
                  />
                  <span className="text-sm text-muted-foreground">%</span>
                </div>
              </div>
            </div>
          )}

          {/* Personal message */}
          <div className="space-y-1.5">
            <Label className="text-sm">Personal message <span className="text-xs text-muted-foreground">(optional)</span></Label>
            <Textarea
              rows={2}
              placeholder="Looking forward to having you on the team!"
              value={personalMessage}
              onChange={(e) => setPersonalMessage(e.target.value)}
            />
          </div>

          {/* Footer */}
          <div className="flex justify-end gap-2 pt-2">
            <Button type="button" variant="ghost" onClick={() => onOpenChange(false)}>
              Cancel
            </Button>
            <Button type="submit" disabled={sending}>
              {sending && <Loader2 className="h-4 w-4 mr-2 animate-spin" />}
              Send Invite →
            </Button>
          </div>
        </form>
      </DialogContent>
    </Dialog>
  )
}

