type Role = 'owner' | 'admin' | 'artist' | 'receptionist' | 'guest_artist'

const ROLE_OPTIONS: { value: Role; label: string }[] = [
  { value: 'owner', label: 'Owner' },
  { value: 'admin', label: 'Admin' },
  { value: 'artist', label: 'Artist' },
  { value: 'receptionist', label: 'Receptionist' },
  { value: 'guest_artist', label: 'Guest Artist' },
]

const ROLE_CLASS: Record<string, string> = {
  owner:        'chip-role-owner',
  admin:        'chip-role-admin',
  artist:       'chip-role-artist',
  receptionist: 'chip-role-receptionist',
  guest_artist: 'chip-role-guest-artist',
}

const ROLE_LABEL: Record<string, string> = {
  owner:        'Owner',
  admin:        'Admin',
  artist:       'Artist',
  receptionist: 'Receptionist',
  guest_artist: 'Guest Artist',
}

interface ChangeRoleDialogProps {
  open: boolean
  onOpenChange: (open: boolean) => void
  memberName: string
  currentRole: Role
  isOwner: boolean
  onConfirm: (newRole: Role, auditNote: string) => Promise<void>
}

export function ChangeRoleDialog({
  open,
  onOpenChange,
  memberName,
  currentRole,
  isOwner,
  onConfirm,
}: ChangeRoleDialogProps) {
  const [selectedRole, setSelectedRole] = useState<Role>(currentRole)
  const [auditNote, setAuditNote] = useState('')
  const [saving, setSaving] = useState(false)

  // Admins cannot grant owner role
  const availableRoles = isOwner
    ? ROLE_OPTIONS
    : ROLE_OPTIONS.filter((r) => r.value !== 'owner')

  const handleConfirm = async () => {
    if (selectedRole === currentRole) {
      onOpenChange(false)
      return
    }
    setSaving(true)
    try {
      await onConfirm(selectedRole, auditNote)
      onOpenChange(false)
      setAuditNote('')
    } finally {
      setSaving(false)
    }
  }

  return (
    <Dialog open={open} onOpenChange={onOpenChange}>
      <DialogContent className="max-w-sm">
        <DialogHeader>
          <DialogTitle>Change Role for {memberName}</DialogTitle>
        </DialogHeader>

        <div className="space-y-4">
          <div className="flex items-center gap-2 text-sm text-muted-foreground">
            <span>Current role:</span>
            <span
              className={cn(
                'inline-flex h-5 items-center rounded-full px-2 text-[10px] font-medium',
                ROLE_CLASS[currentRole],
              )}
            >
              {ROLE_LABEL[currentRole]}
            </span>
          </div>

          <div className="space-y-1.5">
            <Label className="text-sm">New role</Label>
            <RadioGroup
              value={selectedRole}
              onValueChange={(v) => setSelectedRole(v as Role)}
              className="space-y-1"
            >
              {availableRoles.map((r) => (
                <label
                  key={r.value}
                  className={cn(
                    'flex items-center gap-2.5 px-3 py-2 rounded-lg border cursor-pointer transition-colors duration-100',
                    selectedRole === r.value
                      ? 'border-primary/50 bg-primary/[0.06]'
                      : 'border-border/50 hover:border-border',
                  )}
                >
                  <RadioGroupItem value={r.value} />
                  <span className="text-sm font-medium">{r.label}</span>
                </label>
              ))}
            </RadioGroup>
          </div>

          <div className="space-y-1.5">
            <Label className="text-sm text-muted-foreground">
              Reason for role change{' '}
              <span className="text-xs">(optional — logged to audit)</span>
            </Label>
            <Textarea
              rows={2}
              placeholder="e.g. Promoted to admin after 6 months"
              value={auditNote}
              onChange={(e) => setAuditNote(e.target.value)}
            />
          </div>
        </div>

        <DialogFooter>
          <Button variant="ghost" onClick={() => onOpenChange(false)}>
            Cancel
          </Button>
          <Button
            onClick={() => void handleConfirm()}
            disabled={saving || selectedRole === currentRole}
          >
            {saving && <Loader2 className="h-4 w-4 mr-2 animate-spin" />}
            Confirm Change
          </Button>
        </DialogFooter>
      </DialogContent>
    </Dialog>
  )
}

'use client'

import { useState } from 'react'
import {
  Table,
  TableBody,
  TableCell,
