import { ChangeRoleDialog } from './ChangeRoleDialog'
import { usePermissions } from '@/lib/team/permissions-context'

type Role = 'owner' | 'admin' | 'artist' | 'receptionist' | 'guest_artist'

const ROLE_CLASS: Record<string, string> = {
  owner:        'chip-role-owner',
  admin:        'chip-role-admin',
  artist:       'chip-role-artist',
  receptionist: 'chip-role-receptionist',
  guest_artist: 'chip-role-guest-artist',
}
const ROLE_LABEL: Record<string, string> = {
  owner:        'Owner',
  admin:        'Admin',
  artist:       'Artist',
  receptionist: 'Receptionist',
  guest_artist: 'Guest Artist',
}

export interface TeamMember {
  user_id: string
  full_name: string | null
  email: string
  avatar_url: string | null
  role: Role
  last_active_at: string | null
  joined_at: string
  deactivated_at: string | null
}

interface TeamMembersTableProps {
  members: TeamMember[]
  currentUserId: string
  onRefresh: () => void
}

function getInitials(name: string | null, email: string): string {
  if (name) {
    return name
      .split(' ')
      .map((n) => n[0])
      .slice(0, 2)
      .join('')
      .toUpperCase()
  }
  return email[0].toUpperCase()
}

export function TeamMembersTable({ members, currentUserId, onRefresh }: TeamMembersTableProps) {
  const { canDo } = usePermissions()
  const isOwner = canDo('admin.change_roles')
  const isAdmin = isOwner || canDo('settings.team')

  const [changeRoleTarget, setChangeRoleTarget] = useState<TeamMember | null>(null)
  const [deactivateTarget, setDeactivateTarget] = useState<TeamMember | null>(null)
  const [reactivateTarget, setReactivateTarget] = useState<TeamMember | null>(null)
  const [showDeactivated, setShowDeactivated] = useState(false)

  const activeMembers = members.filter((m) => !m.deactivated_at)
  const deactivatedMembers = members.filter((m) => m.deactivated_at)

  const handleChangeRole = async (member: TeamMember, newRole: Role, auditNote: string) => {
    try {
      const res = await fetch(`/api/studio-members/${member.user_id}`, {
        method: 'PATCH',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ new_role: newRole, audit_note: auditNote }),
      })
      if (!res.ok) throw new Error('Failed')
      toast(`${member.full_name ?? member.email}'s role changed to ${ROLE_LABEL[newRole]}`)
      onRefresh()
    } catch {
      toast.error('Failed to change role')
    }
  }

  const handleDeactivate = async () => {
    if (!deactivateTarget) return
    try {
      const res = await fetch(`/api/studio-members/${deactivateTarget.user_id}`, {
        method: 'DELETE',
      })
      if (!res.ok) throw new Error('Failed')
      toast(`${deactivateTarget.full_name ?? deactivateTarget.email} has been deactivated`, {
        duration: 6000,
      })
      setDeactivateTarget(null)
      onRefresh()
    } catch {
      toast.error('Failed to deactivate member')
    }
  }

  const handleReactivate = async () => {
    if (!reactivateTarget) return
    try {
      const res = await fetch(`/api/studio-members/${reactivateTarget.user_id}/reactivate`, {
        method: 'POST',
      })
      if (!res.ok) throw new Error('Failed')
      toast.success(`${reactivateTarget.full_name ?? reactivateTarget.email} has been reactivated`)
      setReactivateTarget(null)
      onRefresh()
    } catch {
      toast.error('Failed to reactivate member')
    }
  }

  const renderRow = (member: TeamMember) => {
    const isDeactivated = !!member.deactivated_at
    const isSelf = member.user_id === currentUserId

    return (
      <TableRow key={member.user_id} className={cn(isDeactivated && 'opacity-50')}>
        <TableCell>
          <div className="flex items-center gap-3">
            <Avatar className="h-8 w-8">
              <AvatarImage src={member.avatar_url ?? undefined} />
              <AvatarFallback className="text-xs font-medium">
                {getInitials(member.full_name, member.email)}
              </AvatarFallback>
            </Avatar>
            <div className="flex flex-col">
              <p className="text-sm font-medium">{member.full_name ?? '—'}</p>
              <p className="text-xs text-muted-foreground">{member.email}</p>
            </div>
          </div>
        </TableCell>

        <TableCell>
          <span
            className={cn(
              'inline-flex h-5 items-center rounded-full px-2 text-[10px] font-medium',
              ROLE_CLASS[member.role],
            )}
          >
            {ROLE_LABEL[member.role]}
          </span>
        </TableCell>

        <TableCell className="text-sm text-muted-foreground tabular-nums">
          {member.last_active_at
            ? formatDistanceToNow(new Date(member.last_active_at), { addSuffix: true })
            : 'Never'}
        </TableCell>

        <TableCell>
          {isDeactivated ? (
            <span className="badge-deactivated inline-flex h-5 items-center rounded-full px-2 text-[10px] font-medium">
              Deactivated
            </span>
          ) : (
            <span className="badge-artist-active inline-flex h-5 items-center rounded-full px-2 text-[10px] font-medium">
              Active
            </span>
          )}
        </TableCell>

        <TableCell onClick={(e) => e.stopPropagation()}>
          {!isSelf && (
            <DropdownMenu>
              <DropdownMenuTrigger asChild>
                <Button variant="ghost" size="icon" className="h-7 w-7">
                  <MoreHorizontal className="h-4 w-4" />
                </Button>
              </DropdownMenuTrigger>
              <DropdownMenuContent align="end">
                {isOwner && !isDeactivated && (
                  <DropdownMenuItem onClick={() => setChangeRoleTarget(member)}>
                    Change Role
                  </DropdownMenuItem>
                )}
                {isAdmin && !isDeactivated && (
                  <DropdownMenuItem
                    className="text-destructive"
                    onClick={() => setDeactivateTarget(member)}
                  >
                    Deactivate
                  </DropdownMenuItem>
                )}
                {isAdmin && isDeactivated && (
                  <DropdownMenuItem onClick={() => setReactivateTarget(member)}>
                    Reactivate
                  </DropdownMenuItem>
                )}
                {!isOwner && !isAdmin && (
                  <DropdownMenuItem disabled>No actions available</DropdownMenuItem>
                )}
              </DropdownMenuContent>
            </DropdownMenu>
          )}
        </TableCell>
      </TableRow>
    )
  }

  if (members.length === 0) {
    return (
      <div className="flex flex-col items-center gap-3 py-16 px-4">
        <UserPlus className="h-10 w-10 text-muted-foreground/40" />
        <p className="text-sm font-semibold">No team members yet</p>
        <p className="text-sm text-muted-foreground text-center max-w-xs">
          Invite your first team member to start collaborating.
        </p>
      </div>
    )
  }

  return (
    <>
      <div className="overflow-x-auto">
        <Table>
          <TableHeader>
            <TableRow>
              <TableHead>Name &amp; Email</TableHead>
              <TableHead className="w-[130px]">Role</TableHead>
              <TableHead className="w-[120px]">Last Active</TableHead>
              <TableHead className="w-[100px]">Status</TableHead>
              <TableHead className="w-12" />
            </TableRow>
          </TableHeader>
          <TableBody>
            {activeMembers.map(renderRow)}
          </TableBody>
        </Table>
      </div>

      {deactivatedMembers.length > 0 && (
        <div className="mt-4">
          <div className="flex items-center gap-3 px-4 mb-2">
            <Separator className="flex-1" />
            <Button
              variant="ghost"
              size="sm"
              className="text-xs text-muted-foreground h-6"
              onClick={() => setShowDeactivated((v) => !v)}
            >
              {showDeactivated
                ? `Hide deactivated (${deactivatedMembers.length})`
                : `Show deactivated (${deactivatedMembers.length})`}
            </Button>
            <Separator className="flex-1" />
          </div>
          {showDeactivated && (
            <div className="overflow-x-auto">
              <Table>
                <TableBody>
                  {deactivatedMembers.map(renderRow)}
                </TableBody>
              </Table>
            </div>
          )}
        </div>
      )}

      {/* Change role dialog */}
      {changeRoleTarget && (
        <ChangeRoleDialog
          open={!!changeRoleTarget}
          onOpenChange={(open) => { if (!open) setChangeRoleTarget(null) }}
          memberName={changeRoleTarget.full_name ?? changeRoleTarget.email}
          currentRole={changeRoleTarget.role}
          isOwner={isOwner}
          onConfirm={(newRole, auditNote) => handleChangeRole(changeRoleTarget, newRole, auditNote)}
        />
      )}

      {/* Deactivate confirmation */}
      <AlertDialog open={!!deactivateTarget} onOpenChange={(open) => { if (!open) setDeactivateTarget(null) }}>
        <AlertDialogContent>
          <AlertDialogHeader>
            <AlertDialogTitle>
              Deactivate {deactivateTarget?.full_name ?? deactivateTarget?.email}?
            </AlertDialogTitle>
            <AlertDialogDescription>
              They will lose access to the studio immediately. Their bookings and records are retained.
            </AlertDialogDescription>
          </AlertDialogHeader>
          <AlertDialogFooter>
            <AlertDialogCancel>Cancel</AlertDialogCancel>
            <AlertDialogAction
              className="bg-destructive text-destructive-foreground hover:bg-destructive/90"
              onClick={() => void handleDeactivate()}
            >
              Deactivate
            </AlertDialogAction>
          </AlertDialogFooter>
        </AlertDialogContent>
      </AlertDialog>

      {/* Reactivate confirmation */}
      <AlertDialog open={!!reactivateTarget} onOpenChange={(open) => { if (!open) setReactivateTarget(null) }}>
        <AlertDialogContent>
          <AlertDialogHeader>
            <AlertDialogTitle>
              Reactivate {reactivateTarget?.full_name ?? reactivateTarget?.email}?
            </AlertDialogTitle>
            <AlertDialogDescription>
              They will regain access to the studio with their previous role.
            </AlertDialogDescription>
          </AlertDialogHeader>
          <AlertDialogFooter>
            <AlertDialogCancel>Cancel</AlertDialogCancel>
            <AlertDialogAction onClick={() => void handleReactivate()}>
              Reactivate
            </AlertDialogAction>
          </AlertDialogFooter>
        </AlertDialogContent>
      </AlertDialog>
    </>
  )
}

