import { formatDistanceToNow, differenceInDays, isPast } from 'date-fns'
import { cn } from '@/lib/utils'
import { useState } from 'react'

const ROLE_CLASS: Record<string, string> = {
  owner:        'chip-role-owner',
  admin:        'chip-role-admin',
  artist:       'chip-role-artist',
  receptionist: 'chip-role-receptionist',
  guest_artist: 'chip-role-guest-artist',
}
const ROLE_LABEL: Record<string, string> = {
  owner:        'Owner',
  admin:        'Admin',
  artist:       'Artist',
  receptionist: 'Receptionist',
  guest_artist: 'Guest Artist',
}

export interface TeamInvite {
  id: string
  email: string
  role: string
  invited_by_name: string | null
  created_at: string
  expires_at: string
  status: 'pending' | 'accepted' | 'declined' | 'expired' | 'revoked'
}

interface TeamInvitesTableProps {
  invites: TeamInvite[]
  onRefresh: () => void
}

function ExpiryCell({ expiresAt, status }: { expiresAt: string; status: string }) {
  const expired = isPast(new Date(expiresAt)) || status === 'expired'
  if (expired) {
    return (
      <span className="inline-flex h-5 items-center rounded-full px-2 text-[10px] font-medium bg-muted text-muted-foreground border border-border/40">
        Expired
      </span>
    )
  }
  const days = differenceInDays(new Date(expiresAt), new Date())
  return (
    <span className={cn('text-sm tabular-nums', days < 2 && 'text-amber-500')}>
      {days === 0 ? 'Today' : `${days} day${days !== 1 ? 's' : ''} left`}
    </span>
  )
}

function StatusBadge({ status }: { status: string }) {
  const cls: Record<string, string> = {
    pending:  'bg-amber-500/10 text-amber-400 border-amber-500/30',
    accepted: 'bg-emerald-500/10 text-emerald-400 border-emerald-500/30',
    declined: 'bg-muted text-muted-foreground border-border/40',
    expired:  'bg-muted text-muted-foreground border-border/40',
    revoked:  'bg-red-500/10 text-red-400 border-red-500/30',
  }
  return (
    <span
      className={cn(
        'inline-flex h-5 items-center rounded-full px-2 text-[10px] font-medium border capitalize',
        cls[status] ?? cls.expired,
      )}
    >
      {status}
    </span>
  )
}

export function TeamInvitesTable({ invites, onRefresh }: TeamInvitesTableProps) {
  const [revokeTarget, setRevokeTarget] = useState<TeamInvite | null>(null)
  const [actioning, setActioning] = useState<string | null>(null)

  const handleResend = async (invite: TeamInvite) => {
    setActioning(invite.id)
    try {
      const res = await fetch(`/api/team-invites/${invite.id}/resend`, { method: 'POST' })
      if (!res.ok) throw new Error('Failed')
      toast.success(`Invite resent to ${invite.email}`)
      onRefresh()
    } catch {
      toast.error('Failed to resend invite')
    } finally {
      setActioning(null)
    }
  }

  const handleRevoke = async () => {
    if (!revokeTarget) return
    setActioning(revokeTarget.id)
    try {
      const res = await fetch(`/api/team-invites/${revokeTarget.id}`, { method: 'DELETE' })
      if (!res.ok) throw new Error('Failed')
      toast(`Invite to ${revokeTarget.email} revoked`)
      setRevokeTarget(null)
      onRefresh()
    } catch {
      toast.error('Failed to revoke invite')
    } finally {
      setActioning(null)
    }
  }

  if (invites.length === 0) {
    return (
      <div className="flex flex-col items-center gap-3 py-16 px-4">
        <MailCheck className="h-10 w-10 text-muted-foreground/40" />
        <p className="text-sm font-semibold">No pending invites</p>
        <p className="text-sm text-muted-foreground text-center max-w-xs">
          No pending invites. Invite new team members anytime.
        </p>
      </div>
    )
  }

  return (
    <>
      <div className="overflow-x-auto">
        <Table>
          <TableHeader>
            <TableRow>
              <TableHead>Email</TableHead>
              <TableHead className="w-[130px]">Role</TableHead>
              <TableHead className="w-[140px]">Invited By</TableHead>
              <TableHead className="w-[120px]">Sent</TableHead>
              <TableHead className="w-[120px]">Expires</TableHead>
              <TableHead className="w-[100px]">Status</TableHead>
              <TableHead className="w-12" />
            </TableRow>
          </TableHeader>
          <TableBody>
            {invites.map((invite) => (
              <TableRow key={invite.id}>
                <TableCell className="text-sm">{invite.email}</TableCell>

                <TableCell>
                  <span
                    className={cn(
                      'inline-flex h-5 items-center rounded-full px-2 text-[10px] font-medium',
                      ROLE_CLASS[invite.role] ?? 'chip-role-artist',
                    )}
                  >
                    {ROLE_LABEL[invite.role] ?? invite.role}
                  </span>
                </TableCell>

                <TableCell className="text-sm text-muted-foreground">
                  {invite.invited_by_name ?? '—'}
                </TableCell>

                <TableCell className="text-sm text-muted-foreground tabular-nums">
                  {formatDistanceToNow(new Date(invite.created_at), { addSuffix: true })}
                </TableCell>

                <TableCell>
                  <ExpiryCell expiresAt={invite.expires_at} status={invite.status} />
                </TableCell>

                <TableCell>
                  <StatusBadge status={invite.status} />
                </TableCell>

                <TableCell onClick={(e) => e.stopPropagation()}>
                  {(invite.status === 'pending' || invite.status === 'expired') && (
                    <DropdownMenu>
                      <DropdownMenuTrigger asChild>
                        <Button
                          variant="ghost"
                          size="icon"
                          className="h-7 w-7"
                          disabled={actioning === invite.id}
                        >
                          <MoreHorizontal className="h-4 w-4" />
                        </Button>
                      </DropdownMenuTrigger>
                      <DropdownMenuContent align="end">
                        <DropdownMenuItem onClick={() => void handleResend(invite)}>
                          Resend
                        </DropdownMenuItem>
                        {invite.status === 'pending' && (
                          <DropdownMenuItem
                            className="text-destructive"
                            onClick={() => setRevokeTarget(invite)}
                          >
                            Revoke
                          </DropdownMenuItem>
                        )}
                      </DropdownMenuContent>
                    </DropdownMenu>
                  )}
                </TableCell>
              </TableRow>
            ))}
          </TableBody>
        </Table>
      </div>

      {/* Revoke confirmation */}
      <AlertDialog open={!!revokeTarget} onOpenChange={(open) => { if (!open) setRevokeTarget(null) }}>
        <AlertDialogContent>
          <AlertDialogHeader>
            <AlertDialogTitle>Revoke invite to {revokeTarget?.email}?</AlertDialogTitle>
            <AlertDialogDescription>
              This invite link will no longer work. You can resend a new invite at any time.
            </AlertDialogDescription>
          </AlertDialogHeader>
          <AlertDialogFooter>
            <AlertDialogCancel>Cancel</AlertDialogCancel>
            <AlertDialogAction
              className="bg-destructive text-destructive-foreground hover:bg-destructive/90"
              onClick={() => void handleRevoke()}
            >
              Revoke
            </AlertDialogAction>
          </AlertDialogFooter>
        </AlertDialogContent>
      </AlertDialog>
    </>
  )
}

'use client'

import { useState, useEffect, useCallback } from 'react'
import type { Metadata } from 'next'
import { Tabs, TabsContent, TabsList, TabsTrigger } from '@/components/ui/tabs'
import { Button } from '@/components/ui/button'
import { Skeleton } from '@/components/ui/skeleton'
import { Alert, AlertDescription } from '@/components/ui/alert'
import { AlertCircle, RefreshCw } from 'lucide-react'
import { TeamMembersTable, type TeamMember } from '@/components/settings/team/TeamMembersTable'
import { TeamInvitesTable, type TeamInvite } from '@/components/settings/team/TeamInvitesTable'
import { InviteModal } from '@/components/settings/team/InviteModal'

export default function TeamPage() {
  const [members, setMembers] = useState<TeamMember[]>([])
  const [invites, setInvites] = useState<TeamInvite[]>([])
  const [currentUserId, setCurrentUserId] = useState('')
  const [loading, setLoading] = useState(true)
  const [error, setError] = useState<string | null>(null)
  const [showInviteModal, setShowInviteModal] = useState(false)

  const fetchData = useCallback(async () => {
    setLoading(true)
    setError(null)
    try {
      const [membersRes, invitesRes, meRes] = await Promise.all([
        fetch('/api/studio-members'),
        fetch('/api/team-invites'),
        fetch('/api/profile'),
      ])

      if (!membersRes.ok) throw new Error('Failed to fetch members')
      const membersJson = await membersRes.json() as { data: TeamMember[] }
      setMembers(membersJson.data ?? [])

      if (invitesRes.ok) {
        const invitesJson = await invitesRes.json() as { data: TeamInvite[] }
        setInvites(invitesJson.data ?? [])
      }

      if (meRes.ok) {
        const meJson = await meRes.json() as { data: { id: string } }
        setCurrentUserId(meJson.data?.id ?? '')
      }
    } catch {
      setError('Could not load team data. Please try again.')
    } finally {
      setLoading(false)
    }
  }, [])

  useEffect(() => { void fetchData() }, [fetchData])

  const pendingCount = invites.filter((i) => i.status === 'pending').length
  const activeCount = members.filter((m) => !m.deactivated_at).length

  return (
    <div className="flex flex-col min-h-0">
      <div className="flex items-center justify-between px-6 py-4 border-b border-border/50">
        <h1 className="text-2xl font-bold tracking-tight">Team &amp; Roles</h1>
        <Button size="sm" onClick={() => setShowInviteModal(true)}>
          + Invite Member
        </Button>
      </div>

      {error && !loading && (
        <div className="p-6">
          <Alert variant="destructive">
            <AlertCircle className="h-4 w-4" />
            <AlertDescription className="flex items-center justify-between">
              <span>{error}</span>
              <Button variant="ghost" size="sm" onClick={() => void fetchData()} className="ml-4 h-7 gap-1.5">
                <RefreshCw className="h-3.5 w-3.5" />
                Retry
              </Button>
            </AlertDescription>
          </Alert>
        </div>
      )}

      <Tabs defaultValue="members" className="mt-0 flex-1">
        <TabsList className="w-full justify-start border-b rounded-none bg-transparent h-auto px-6 gap-0">
          <TabsTrigger
            value="members"
            className="rounded-none border-b-2 border-transparent data-[state=active]:border-primary px-4 pb-3 pt-0 text-sm font-medium"
          >
            Members {!loading && `(${activeCount})`}
          </TabsTrigger>
          <TabsTrigger
            value="invites"
            className="rounded-none border-b-2 border-transparent data-[state=active]:border-primary px-4 pb-3 pt-0 text-sm font-medium"
          >
            Pending Invites {!loading && pendingCount > 0 && `(${pendingCount})`}
          </TabsTrigger>
        </TabsList>

        <TabsContent value="members" className="mt-0 p-6">
          {loading ? (
            <div className="space-y-2">
              {Array.from({ length: 4 }).map((_, i) => (
                <Skeleton key={i} className="h-14 rounded-lg" />
              ))}
            </div>
          ) : (
            <TeamMembersTable
              members={members}
              currentUserId={currentUserId}
              onRefresh={() => void fetchData()}
            />
          )}
        </TabsContent>

        <TabsContent value="invites" className="mt-0 p-6">
          {loading ? (
            <div className="space-y-2">
              {Array.from({ length: 2 }).map((_, i) => (
                <Skeleton key={i} className="h-14 rounded-lg" />
              ))}
            </div>
          ) : (
            <TeamInvitesTable
              invites={invites}
              onRefresh={() => void fetchData()}
            />
          )}
        </TabsContent>
      </Tabs>

      {showInviteModal && (
        <InviteModal
          open={showInviteModal}
          onOpenChange={setShowInviteModal}
          onSuccess={() => void fetchData()}
        />
      )}
    </div>
  )
}

