import type { NextRequest } from 'next/server'
import { NextResponse } from 'next/server'
import { z } from 'zod'
import { createClient, getAuthenticatedUser } from '@/lib/supabase/server'
import { authedRatelimit } from '@/lib/rate-limit'
import { logger } from '@/lib/logger'
import { updateLastActive } from '@/lib/team/last-active'

const CreateInviteSchema = z.object({
  email: z.string().email({ message: 'invalid_email' }),
  role: z.enum(['admin', 'artist', 'receptionist', 'guest_artist', 'owner']),
  commission_pct: z.number().min(0).max(100).nullable().optional(),
  personal_message: z.string().max(500).nullable().optional(),
  artist_id: z.string().uuid().nullable().optional(),
})

export async function GET(_request: NextRequest) {
  const authUser = await getAuthenticatedUser()
  if (!authUser) {
    return NextResponse.json({ error: 'Unauthorized' }, { status: 401 })
  }

  const { success } = await authedRatelimit.limit(authUser.user.id)
  if (!success) {
    return NextResponse.json({ error: 'Too many requests' }, { status: 429 })
  }

  try {
    const supabase = await createClient()

    const { data, error } = await supabase
      .from('team_invites')
      .select(`
        id, email, role, status, expires_at, created_at, personal_message,
        invited_by, profiles:invited_by(full_name)
      `)
      .eq('studio_id', authUser.studioId)
      .order('created_at', { ascending: false })

    if (error) {
      logger.error({ err: error }, 'team-invites list failed')
      return NextResponse.json({ error: 'Failed to fetch invites' }, { status: 500 })
    }

    const invites = (data ?? []).map((row) => ({
      id: row.id,
      email: row.email,
      role: row.role,
      status: row.status,
      expires_at: row.expires_at,
      created_at: row.created_at,
      personal_message: row.personal_message,
      invited_by_name: (row.profiles as { full_name: string | null } | null)?.full_name ?? null,
    }))

    return NextResponse.json({ data: invites })
  } catch (err) {
    logger.error({ err }, 'team-invites GET unexpected error')
    return NextResponse.json({ error: 'Internal server error' }, { status: 500 })
  }
}

export async function POST(request: NextRequest) {
  const authUser = await getAuthenticatedUser()
  if (!authUser) {
    return NextResponse.json({ error: 'Unauthorized' }, { status: 401 })
  }

  const { success } = await authedRatelimit.limit(authUser.user.id)
  if (!success) {
    return NextResponse.json({ error: 'Too many requests' }, { status: 429 })
  }

  const body = CreateInviteSchema.safeParse(await request.json())
  if (!body.success) {
    const firstError = body.error.issues[0]?.message
    return NextResponse.json(
      { error: firstError ?? 'Invalid input' },
      { status: 400 },
    )
  }

  try {
    const supabase = await createClient()

    // Check if email is already a member
    const { data: existingMember } = await supabase
      .from('studio_members')
      .select('user_id, profiles:user_id(email)')
      .eq('studio_id', authUser.studioId)
      .is('deactivated_at', null)

    const emails = (existingMember ?? []).map(
      (m) => ((m.profiles as { email: string } | null)?.email ?? '').toLowerCase().trim(),
    )
    if (emails.includes(body.data.email.toLowerCase().trim())) {
      return NextResponse.json({ error: 'already_a_member' }, { status: 409 })
    }

    // Call the create_team_invite RPC
    const { data, error } = await supabase.rpc('create_team_invite', {
      p_studio_id: authUser.studioId,
      p_email: body.data.email,
      p_role: body.data.role,
      p_commission_pct: body.data.commission_pct ?? null,
      p_personal_message: body.data.personal_message ?? null,
      p_artist_id: body.data.artist_id ?? null,
    })

    if (error) {
      logger.error({ err: error }, 'create_team_invite RPC failed')
      return NextResponse.json({ error: 'Failed to create invite' }, { status: 500 })
    }

    await updateLastActive(authUser.studioId)

    // Enqueue invite email via worker
    // TODO: enqueue via BullMQ worker when email worker is set up

    return NextResponse.json({ data })
  } catch (err) {
    logger.error({ err }, 'team-invites POST unexpected error')
    return NextResponse.json({ error: 'Internal server error' }, { status: 500 })
  }
}

