import type { NextRequest } from 'next/server'
import { NextResponse } from 'next/server'
import { createClient, getAuthenticatedUser } from '@/lib/supabase/server'
import { authedRatelimit } from '@/lib/rate-limit'
import { logger } from '@/lib/logger'
import { updateLastActive } from '@/lib/team/last-active'

export async function POST(
  _request: NextRequest,
  { params }: { params: Promise<{ id: string }> },
) {
  const authUser = await getAuthenticatedUser()
  if (!authUser) {
    return NextResponse.json({ error: 'Unauthorized' }, { status: 401 })
  }

  const { success } = await authedRatelimit.limit(authUser.user.id)
  if (!success) {
    return NextResponse.json({ error: 'Too many requests' }, { status: 429 })
  }

  const { id } = await params

  try {
    const supabase = await createClient()

    // Fetch original invite
    const { data: invite, error: fetchError } = await supabase
      .from('team_invites')
      .select('email, role, commission_default_pct, personal_message, artist_id')
      .eq('id', id)
      .eq('studio_id', authUser.studioId)
      .single()

    if (fetchError || !invite) {
      return NextResponse.json({ error: 'Invite not found' }, { status: 404 })
    }

    // Expire the old invite
    await supabase
      .from('team_invites')
      .update({ status: 'expired' })
      .eq('id', id)
      .eq('studio_id', authUser.studioId)

    // Create new invite
    const { data: newInvite, error: createError } = await supabase.rpc('create_team_invite', {
      p_studio_id: authUser.studioId,
      p_email: invite.email,
      p_role: invite.role,
      p_commission_pct: invite.commission_default_pct ?? null,
      p_personal_message: invite.personal_message ?? null,
      p_artist_id: invite.artist_id ?? null,
    })

    if (createError) {
      logger.error({ err: createError }, 'resend create_team_invite failed')
      return NextResponse.json({ error: 'Failed to resend invite' }, { status: 500 })
    }

    await updateLastActive(authUser.studioId)

    return NextResponse.json({ data: newInvite })
  } catch (err) {
    logger.error({ err }, 'team-invite resend unexpected error')
    return NextResponse.json({ error: 'Internal server error' }, { status: 500 })
  }
}

import type { NextRequest } from 'next/server'
import { NextResponse } from 'next/server'
import { createClient } from '@/lib/supabase/server'
import { createServiceRoleClient } from '@/lib/supabase/server'
import { logger } from '@/lib/logger'

export async function POST(
  _request: NextRequest,
  { params }: { params: Promise<{ token: string }> },
) {
  const { token } = await params

  // Auth check — must be logged in to accept
  const supabase = await createClient()
  const { data: { user } } = await supabase.auth.getUser()
  if (!user) {
    return NextResponse.json({ error: 'Unauthorized' }, { status: 401 })
  }

  try {
    // Call the accept_team_invite RPC — validates email match internally
    const { data, error } = await supabase.rpc('accept_team_invite', {
      p_invite_token: token,
    })

    if (error) {
      const msg = error.message ?? ''
      if (msg.includes('email_mismatch')) {
        return NextResponse.json({ error: 'email_mismatch' }, { status: 409 })
      }
      if (msg.includes('already_a_member')) {
        return NextResponse.json({ error: 'already_a_member' }, { status: 409 })
      }
      if (msg.includes('invite_not_found') || msg.includes('not found')) {
        return NextResponse.json({ error: 'invite_not_found' }, { status: 404 })
      }
      if (msg.includes('expired')) {
        return NextResponse.json({ error: 'expired' }, { status: 410 })
      }
      logger.error({ err: error, token }, 'accept_team_invite RPC failed')
      return NextResponse.json({ error: 'Failed to accept invite' }, { status: 500 })
    }

    // CRITICAL: The RPC does NOT copy commission_default_pct to artists table.
    // We must do this here if the invite had a commission value and an artist_id.
    const acceptResult = data as {
      invite_id?: string
      studio_id?: string
      role?: string
      artist_id?: string | null
      commission_default_pct?: number | null
    } | null

    if (
      acceptResult?.artist_id &&
      acceptResult.commission_default_pct != null &&
      acceptResult.studio_id
    ) {
      // Use service-role client to bypass RLS for this cross-table write
      const adminClient = createServiceRoleClient()
      const { error: commissionError } = await adminClient
        .from('artists')
        .update({ commission_default_pct: acceptResult.commission_default_pct })
        .eq('id', acceptResult.artist_id)
        .eq('studio_id', acceptResult.studio_id)

      if (commissionError) {
        // Log but don't fail — member was accepted, commission update is secondary
        logger.error(
          { err: commissionError, artistId: acceptResult.artist_id },
          'failed to copy commission_default_pct after invite accept',
        )
      }
    }

    return NextResponse.json({ data: acceptResult })
  } catch (err) {
    logger.error({ err, token }, 'team-invite accept unexpected error')
    return NextResponse.json({ error: 'Internal server error' }, { status: 500 })
  }
}

import type { NextRequest } from 'next/server'
import { NextResponse } from 'next/server'
import { createClient, getAuthenticatedUser } from '@/lib/supabase/server'
import { authedRatelimit } from '@/lib/rate-limit'
