import type { NextRequest } from 'next/server'
import { NextResponse } from 'next/server'
import { z } from 'zod'
import { createClient, getAuthenticatedUser } from '@/lib/supabase/server'
import { authedRatelimit } from '@/lib/rate-limit'
import { logger } from '@/lib/logger'
import { logAuditAction } from '@/lib/audit'
import { updateLastActive } from '@/lib/team/last-active'

const ChangeRoleSchema = z.object({
  role: z.enum(['admin', 'artist', 'receptionist', 'guest_artist', 'owner']),
  audit_note: z.string().max(500).nullable().optional(),
})

/**
 * PATCH /api/studio-members/[userId]
 * Change a member's role. Only owners can grant/remove owner role.
 * Only admins/owners can change other roles.
 */
export async function PATCH(
  request: NextRequest,
  { params }: { params: Promise<{ userId: string }> },
) {
  const authUser = await getAuthenticatedUser()
  if (!authUser) {
    return NextResponse.json({ error: 'Unauthorized' }, { status: 401 })
  }

  const { success } = await authedRatelimit.limit(authUser.user.id)
  if (!success) {
    return NextResponse.json({ error: 'Too many requests' }, { status: 429 })
  }

  const { userId } = await params

  // Can't change your own role
  if (userId === authUser.user.id) {
    return NextResponse.json({ error: 'Cannot change your own role' }, { status: 400 })
  }

  const body = ChangeRoleSchema.safeParse(await request.json())
  if (!body.success) {
    return NextResponse.json({ error: body.error.issues[0]?.message ?? 'Invalid input' }, { status: 400 })
  }

  const { role: newRole, audit_note } = body.data

  // Only owners can assign or remove owner role
  if (newRole === 'owner' && authUser.role !== 'owner') {
    return NextResponse.json({ error: 'Only owners can assign owner role' }, { status: 403 })
  }
  if (authUser.role !== 'owner' && authUser.role !== 'admin') {
    return NextResponse.json({ error: 'Forbidden' }, { status: 403 })
  }

  try {
    const supabase = await createClient()

    // Verify target member belongs to this studio
    const { data: target, error: fetchError } = await supabase
      .from('studio_members')
      .select('id, role, user_id')
      .eq('studio_id', authUser.studioId)
      .eq('user_id', userId)
      .is('deactivated_at', null)
      .single()

    if (fetchError || !target) {
      return NextResponse.json({ error: 'Member not found' }, { status: 404 })
    }

    // Admins cannot change role of owners
    if (target.role === 'owner' && authUser.role !== 'owner') {
      return NextResponse.json({ error: 'Cannot change role of an owner' }, { status: 403 })
    }

    const { data: updated, error: updateError } = await supabase
      .from('studio_members')
      .update({ role: newRole })
      .eq('studio_id', authUser.studioId)
      .eq('user_id', userId)
      .select('id, role')
      .single()

    if (updateError || !updated) {
      logger.error({ err: updateError, userId }, 'change_member_role update failed')
      return NextResponse.json({ error: 'Failed to change role' }, { status: 500 })
    }

    await Promise.all([
      updateLastActive(authUser.studioId),
      logAuditAction(
        authUser.user.id,
        'member.role_changed',
        { type: 'studio_member', id: target.id },
        {
          from_role: target.role,
          to_role: newRole,
          note: audit_note ?? null,
        },
        authUser.studioId,
      ),
    ])

    return NextResponse.json({ data: updated })
  } catch (err) {
    logger.error({ err }, 'studio-members PATCH unexpected error')
    return NextResponse.json({ error: 'Internal server error' }, { status: 500 })
  }
}

/**
 * DELETE /api/studio-members/[userId]
 * Soft-deactivate a member. Sets deactivated_at + deactivated_by.
 * Owners cannot be deactivated. A member cannot deactivate themselves.
 */
export async function DELETE(
  _request: NextRequest,
  { params }: { params: Promise<{ userId: string }> },
) {
  const authUser = await getAuthenticatedUser()
  if (!authUser) {
    return NextResponse.json({ error: 'Unauthorized' }, { status: 401 })
  }

  const { success } = await authedRatelimit.limit(authUser.user.id)
  if (!success) {
    return NextResponse.json({ error: 'Too many requests' }, { status: 429 })
  }

  const { userId } = await params

  if (userId === authUser.user.id) {
    return NextResponse.json({ error: 'Cannot deactivate yourself' }, { status: 400 })
  }

  if (authUser.role !== 'owner' && authUser.role !== 'admin') {
    return NextResponse.json({ error: 'Forbidden' }, { status: 403 })
  }

  try {
    const supabase = await createClient()

    const { data: target, error: fetchError } = await supabase
      .from('studio_members')
      .select('id, role, user_id')
      .eq('studio_id', authUser.studioId)
      .eq('user_id', userId)
      .is('deactivated_at', null)
      .single()

    if (fetchError || !target) {
      return NextResponse.json({ error: 'Member not found' }, { status: 404 })
    }

    // Only owners can deactivate other owners
    if (target.role === 'owner' && authUser.role !== 'owner') {
      return NextResponse.json({ error: 'Cannot deactivate an owner' }, { status: 403 })
    }

    const now = new Date().toISOString()

    const { error: updateError } = await supabase
      .from('studio_members')
      .update({
        deactivated_at: now,
        deactivated_by: authUser.user.id,
      })
      .eq('studio_id', authUser.studioId)
      .eq('user_id', userId)

    if (updateError) {
      logger.error({ err: updateError, userId }, 'deactivate_member failed')
      return NextResponse.json({ error: 'Failed to deactivate member' }, { status: 500 })
    }

    await Promise.all([
      updateLastActive(authUser.studioId),
      logAuditAction(
        authUser.user.id,
        'member.deactivated',
        { type: 'studio_member', id: target.id },
        { role: target.role },
        authUser.studioId,
      ),
    ])

    return NextResponse.json({ success: true })
  } catch (err) {
    logger.error({ err }, 'studio-members DELETE unexpected error')
    return NextResponse.json({ error: 'Internal server error' }, { status: 500 })
  }
}

import type { NextRequest } from 'next/server'
import { NextResponse } from 'next/server'
import { createClient, getAuthenticatedUser } from '@/lib/supabase/server'
import { authedRatelimit } from '@/lib/rate-limit'
import { logger } from '@/lib/logger'
import { logAuditAction } from '@/lib/audit'
import { updateLastActive } from '@/lib/team/last-active'

/**
 * POST /api/studio-members/[userId]/reactivate
 * Re-activates a previously deactivated member. Clears deactivated_at + deactivated_by.
 * Only owners and admins can reactivate members.
 */
export async function POST(
  _request: NextRequest,
  { params }: { params: Promise<{ userId: string }> },
) {
  const authUser = await getAuthenticatedUser()
  if (!authUser) {
    return NextResponse.json({ error: 'Unauthorized' }, { status: 401 })
  }

  const { success } = await authedRatelimit.limit(authUser.user.id)
  if (!success) {
    return NextResponse.json({ error: 'Too many requests' }, { status: 429 })
  }

  if (authUser.role !== 'owner' && authUser.role !== 'admin') {
    return NextResponse.json({ error: 'Forbidden' }, { status: 403 })
  }

  const { userId } = await params

  try {
    const supabase = await createClient()

    // Must exist in this studio AND be currently deactivated
    const { data: target, error: fetchError } = await supabase
      .from('studio_members')
      .select('id, role, user_id, deactivated_at')
      .eq('studio_id', authUser.studioId)
      .eq('user_id', userId)
      .not('deactivated_at', 'is', null)
      .single()

    if (fetchError || !target) {
      return NextResponse.json({ error: 'Deactivated member not found' }, { status: 404 })
    }

    const { error: updateError } = await supabase
      .from('studio_members')
      .update({
        deactivated_at: null,
        deactivated_by: null,
      })
      .eq('studio_id', authUser.studioId)
      .eq('user_id', userId)

    if (updateError) {
      logger.error({ err: updateError, userId }, 'reactivate_member failed')
      return NextResponse.json({ error: 'Failed to reactivate member' }, { status: 500 })
    }

    await Promise.all([
      updateLastActive(authUser.studioId),
      logAuditAction(
        authUser.user.id,
        'member.reactivated',
        { type: 'studio_member', id: target.id },
        { role: target.role },
        authUser.studioId,
      ),
    ])

    return NextResponse.json({ success: true })
  } catch (err) {
    logger.error({ err }, 'studio-members reactivate unexpected error')
    return NextResponse.json({ error: 'Internal server error' }, { status: 500 })
  }
}

import type { NextRequest } from 'next/server'
import { NextResponse } from 'next/server'
import { z } from 'zod'
import { createClient, getAuthenticatedUser } from '@/lib/supabase/server'
import { authedRatelimit } from '@/lib/rate-limit'
import { logger } from '@/lib/logger'

const UpdateProfileSchema = z.object({
  full_name: z.string().min(1, 'Name is required').max(100).optional(),
  avatar_url: z.string().url().nullable().optional(),
})

/**
 * GET /api/profile
 * Returns the current authenticated user's profile + studio membership info.
 */
export async function GET(_request: NextRequest) {
  const authUser = await getAuthenticatedUser()
  if (!authUser) {
    return NextResponse.json({ error: 'Unauthorized' }, { status: 401 })
  }

  const { success } = await authedRatelimit.limit(authUser.user.id)
  if (!success) {
    return NextResponse.json({ error: 'Too many requests' }, { status: 429 })
  }

  return NextResponse.json({
    data: {
      id: authUser.user.id,
      email: authUser.user.email,
      full_name: authUser.user.full_name,
      avatar_url: authUser.user.avatar_url,
      is_platform_admin: authUser.user.is_platform_admin,
      studio_id: authUser.studioId,
      role: authUser.role,
    },
  })
}

/**
 * PATCH /api/profile
 * Update the current user's profile fields (full_name, avatar_url).
 */
export async function PATCH(request: NextRequest) {
  const authUser = await getAuthenticatedUser()
  if (!authUser) {
    return NextResponse.json({ error: 'Unauthorized' }, { status: 401 })
  }

  const { success } = await authedRatelimit.limit(authUser.user.id)
  if (!success) {
    return NextResponse.json({ error: 'Too many requests' }, { status: 429 })
  }

  const body = UpdateProfileSchema.safeParse(await request.json())
  if (!body.success) {
    return NextResponse.json(
      { error: body.error.issues[0]?.message ?? 'Invalid input' },
      { status: 400 },
    )
  }

  try {
    const supabase = await createClient()

    const { data, error } = await supabase
      .from('profiles')
      .update({
        ...body.data,
        updated_at: new Date().toISOString(),
      })
      .eq('id', authUser.user.id)
      .select('id, email, full_name, avatar_url')
      .single()

    if (error || !data) {
      logger.error({ err: error }, 'profile PATCH failed')
      return NextResponse.json({ error: 'Failed to update profile' }, { status: 500 })
    }

    return NextResponse.json({ data })
  } catch (err) {
    logger.error({ err }, 'profile PATCH unexpected error')
    return NextResponse.json({ error: 'Internal server error' }, { status: 500 })
  }
}

import type { NextRequest } from 'next/server'
import { NextResponse } from 'next/server'
import { createClient, getAuthenticatedUser } from '@/lib/supabase/server'
import { authedRatelimit } from '@/lib/rate-limit'
import { logger } from '@/lib/logger'

/**
 * GET /api/role-permissions
 * Returns the full role_permissions matrix for the current studio's plan.
 * Used by the PermissionsMatrix UI component on the permissions settings page.
 *
 * Only owners and admins can access this endpoint.
 */
export async function GET(_request: NextRequest) {
  const authUser = await getAuthenticatedUser()
  if (!authUser) {
    return NextResponse.json({ error: 'Unauthorized' }, { status: 401 })
  }

  const { success } = await authedRatelimit.limit(authUser.user.id)
  if (!success) {
    return NextResponse.json({ error: 'Too many requests' }, { status: 429 })
  }

  if (authUser.role !== 'owner' && authUser.role !== 'admin') {
    return NextResponse.json({ error: 'Forbidden' }, { status: 403 })
  }

  try {
    const supabase = await createClient()

    const { data, error } = await supabase
      .from('role_permissions')
      .select('id, role, permission_key, granted')
      .order('role', { ascending: true })
      .order('permission_key', { ascending: true })

    if (error) {
      logger.error({ err: error }, 'role-permissions GET failed')
      return NextResponse.json({ error: 'Failed to fetch permissions' }, { status: 500 })
    }

    // Group by role for easier consumption by the matrix component
    type PermRow = { id: string; role: string; permission_key: string; granted: boolean }

    const byRole = (data ?? []).reduce<Record<string, Record<string, boolean>>>(
      (acc, row: PermRow) => {
        if (!acc[row.role]) acc[row.role] = {}
        acc[row.role][row.permission_key] = row.granted
        return acc
      },
      {},
    )

    return NextResponse.json({ data: byRole, raw: data })
  } catch (err) {
    logger.error({ err }, 'role-permissions GET unexpected error')
    return NextResponse.json({ error: 'Internal server error' }, { status: 500 })
  }
}

import type { NextRequest } from 'next/server'
import { NextResponse } from 'next/server'
import { createPublicClient } from '@/lib/supabase/public'
import { apiRatelimit } from '@/lib/rate-limit'
import { logger } from '@/lib/logger'

/**
 * GET /api/public/invites/[token]
 * Public endpoint — returns invite metadata for the accept-invite page.
 * Uses the anon Supabase client; RLS must permit anon SELECT on team_invites
 * filtered to pending/non-expired rows via a SECURITY DEFINER RPC.
 *
 * Rate-limited by IP to prevent enumeration attacks.
 */
export async function GET(
  request: NextRequest,
  { params }: { params: Promise<{ token: string }> },
) {
  const ip = request.headers.get('x-forwarded-for') ?? 'anonymous'
  const { success } = await apiRatelimit.limit(`pub:invite:${ip}`)
  if (!success) {
    return NextResponse.json({ error: 'Too many requests' }, { status: 429 })
  }

  const { token } = await params

  if (!token || typeof token !== 'string' || token.length < 20) {
    return NextResponse.json({ error: 'invalid_token' }, { status: 400 })
  }

  try {
    const supabase = createPublicClient()

    // Use a SECURITY DEFINER RPC to safely expose invite data to anon
    const { data, error } = await supabase.rpc('public_get_invite_by_token', {
      p_token: token,
    })

    if (error) {
      const msg = error.message ?? ''
      if (msg.includes('not_found') || msg.includes('expired') || msg.includes('not found')) {
        return NextResponse.json({ error: 'invite_not_found' }, { status: 404 })
      }
      logger.error({ err: error, token: token.slice(0, 8) }, 'public_get_invite_by_token failed')
      return NextResponse.json({ error: 'Failed to fetch invite' }, { status: 500 })
    }

    if (!data) {
      return NextResponse.json({ error: 'invite_not_found' }, { status: 404 })
    }

    // data is the RPC return — shape is defined by the Supabase function
    const invite = data as {
      id: string
      email: string
      role: string
      studio_name: string
      studio_logo_url: string | null
      inviter_name: string | null
      personal_message: string | null
      expires_at: string
      status: string
    }

    // Only expose pending invites
    if (invite.status !== 'pending') {
      return NextResponse.json(
        { error: invite.status === 'expired' ? 'expired' : 'invite_not_found' },
        { status: invite.status === 'expired' ? 410 : 404 },
      )
    }

    return NextResponse.json({
      data: {
        id: invite.id,
        email: invite.email,
        role: invite.role,
        studio_name: invite.studio_name,
        studio_logo_url: invite.studio_logo_url,
        inviter_name: invite.inviter_name,
        personal_message: invite.personal_message,
        expires_at: invite.expires_at,
      },
    })
  } catch (err) {
    logger.error({ err, token: token.slice(0, 8) }, 'public invite GET unexpected error')
    return NextResponse.json({ error: 'Internal server error' }, { status: 500 })
  }
}

