                {ROLE_LABEL[role]}
              </th>
            ))}
          </tr>
        </thead>
        <tbody>
          {PERMISSION_GROUPS.map((group, gi) => (
            <>
              {/* Group header row */}
              <tr
                key={`group-${gi}`}
                className="bg-muted/20 border-t border-border/30 first:border-t-0"
              >
                <td
                  colSpan={ROLES.length + 1}
                  className="px-4 py-2 text-xs font-semibold uppercase tracking-wider text-muted-foreground"
                >
                  {group.group}
                </td>
              </tr>
              {/* Permission rows */}
              {group.permissions.map((perm, pi) => (
                <tr
                  key={perm.key}
                  className={cn(
                    'border-t border-border/20 transition-colors hover:bg-muted/20',
                    pi === group.permissions.length - 1 && 'border-b border-border/30',
                  )}
                >
                  <td className="px-4 py-2.5 text-foreground">
                    {perm.label}
                    <span className="ml-2 font-mono text-[10px] text-muted-foreground/60">
                      {perm.key}
                    </span>
                  </td>
                  {ROLES.map((role) => {
                    const granted = isGranted(role, perm.key)
                    return (
                      <td key={role} className="px-3 py-2.5 text-center">
                        {data ? (
                          granted ? (
                            <Check
                              className="mx-auto h-4 w-4 text-emerald-500"
                              aria-label="Granted"
                            />
                          ) : (
                            <X
                              className="mx-auto h-4 w-4 text-muted-foreground/40"
                              aria-label="Not granted"
                            />
                          )
                        ) : (
                          <Loader2 className="mx-auto h-3 w-3 animate-spin text-muted-foreground/40" />
                        )}
                      </td>
                    )
                  })}
                </tr>
              ))}
            </>
          ))}
        </tbody>
      </table>
    </div>
  )
}

'use client'

import { useState, useEffect, useCallback } from 'react'
import { toast } from 'sonner'
import { Loader2, Camera } from 'lucide-react'
import { Button } from '@/components/ui/button'
import { Input } from '@/components/ui/input'
import { Label } from '@/components/ui/label'
import { Skeleton } from '@/components/ui/skeleton'
import { Avatar, AvatarFallback, AvatarImage } from '@/components/ui/avatar'
import { Separator } from '@/components/ui/separator'

interface ProfileData {
  id: string
  email: string
  full_name: string | null
  avatar_url: string | null
  role: string
  studio_id: string
}

export default function ProfilePage() {
  const [profile, setProfile] = useState<ProfileData | null>(null)
  const [loading, setLoading] = useState(true)
  const [saving, setSaving] = useState(false)
  const [fullName, setFullName] = useState('')
  const [isDirty, setIsDirty] = useState(false)

  const fetchProfile = useCallback(async () => {
    setLoading(true)
    try {
      const res = await fetch('/api/profile')
      if (!res.ok) {
        toast.error('Failed to load profile')
        return
      }
      const json = await res.json() as { data: ProfileData }
      const data = json.data
      setProfile(data)
      setFullName(data.full_name ?? '')
    } finally {
      setLoading(false)
    }
  }, [])

  useEffect(() => { void fetchProfile() }, [fetchProfile])

  const handleNameChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    setFullName(e.target.value)
    setIsDirty(true)
  }

  async function handleSave() {
    if (!isDirty || saving) return
    if (!fullName.trim()) {
      toast.error('Display name cannot be empty')
      return
    }
    setSaving(true)
    try {
      const res = await fetch('/api/profile', {
        method: 'PATCH',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ full_name: fullName.trim() }),
      })
      if (!res.ok) {
        const json = await res.json() as { error?: string }
        toast.error(json.error ?? 'Failed to save profile')
        return
      }
      setIsDirty(false)
      toast.success('Profile saved')
    } catch {
      toast.error('Network error. Please try again.')
    } finally {
      setSaving(false)
    }
  }

  const initials = (fullName || profile?.email || '?')
    .split(' ')
    .map((n) => n[0])
    .slice(0, 2)
    .join('')
    .toUpperCase()

  const ROLE_LABEL: Record<string, string> = {
    owner: 'Owner',
    admin: 'Admin',
    artist: 'Artist',
    receptionist: 'Receptionist',
    guest_artist: 'Guest Artist',
  }

  return (
    <div className="flex flex-col min-h-0">
      <div className="flex items-center justify-between px-6 py-4 border-b border-border/50">
        <h1 className="text-2xl font-bold tracking-tight">My Profile</h1>
      </div>

      <div className="max-w-lg space-y-8 p-6">
        {/* Avatar section */}
        <div className="flex items-center gap-5">
          {loading ? (
            <Skeleton className="h-16 w-16 rounded-full" />
          ) : (
            <Avatar className="h-16 w-16 text-lg">
              <AvatarImage src={profile?.avatar_url ?? undefined} alt={fullName} />
              <AvatarFallback>{initials}</AvatarFallback>
            </Avatar>
          )}
          <div>
            {loading ? (
              <div className="space-y-1">
                <Skeleton className="h-4 w-32" />
                <Skeleton className="h-3 w-20" />
              </div>
            ) : (
              <>
                <p className="font-semibold">{fullName || 'No name set'}</p>
                <p className="text-sm text-muted-foreground">
                  {profile ? (ROLE_LABEL[profile.role] ?? profile.role) : '—'}
                </p>
              </>
            )}
          </div>
          <Button
            variant="outline"
            size="sm"
            className="ml-auto gap-1.5"
            disabled
            title="Avatar upload coming soon"
          >
            <Camera className="h-3.5 w-3.5" />
            Change photo
          </Button>
        </div>

        <Separator />

        {/* Personal info */}
        <div className="space-y-4">
          <div className="space-y-1.5">
            <Label htmlFor="full-name">Display name</Label>
            {loading ? (
              <Skeleton className="h-9 rounded-md" />
            ) : (
              <Input
                id="full-name"
                value={fullName}
                onChange={handleNameChange}
                placeholder="Your full name"
                maxLength={100}
              />
            )}
          </div>

          <div className="space-y-1.5">
            <Label htmlFor="email">Email address</Label>
            {loading ? (
              <Skeleton className="h-9 rounded-md" />
            ) : (
              <Input
                id="email"
                value={profile?.email ?? ''}
                readOnly
                className="cursor-not-allowed bg-muted/50 text-muted-foreground"
              />
            )}
            <p className="text-xs text-muted-foreground">
              Email changes are managed through account settings.
            </p>
          </div>
        </div>

        {!loading && (
          <div className="flex gap-3">
            <Button
              onClick={() => void handleSave()}
              disabled={!isDirty || saving}
            >
              {saving ? (
                <><Loader2 className="mr-2 h-4 w-4 animate-spin" /> Saving…</>
              ) : (
                'Save changes'
              )}
            </Button>
            {isDirty && (
              <Button
                variant="ghost"
                onClick={() => {
                  setFullName(profile?.full_name ?? '')
                  setIsDirty(false)
                }}
              >
                Cancel
              </Button>
            )}
          </div>
        )}
      </div>
    </div>
  )
}

