  .from('studio_members')
  .select('id, user_id, role, joined_at, deactivated_at, deactivated_by, last_active_at, invite_id, created_at')
  .eq('studio_id', authUser.studioId)
  .order('joined_at', { ascending: true })

if (error) {
  logger.error({ err: error }, 'studio-members list failed')
  return NextResponse.json({ error: 'Failed to fetch members' }, { status: 500 })
}

const rows = data ?? []
const userIds = rows.map((r) => r.user_id)

// Fetch profiles in one query
