  ? await supabase
      .from('profiles')
      .select('id, full_name, email, avatar_url')
      .in('id', userIds)
  : { data: [] }

type ProfileRow = { id: string; full_name: string | null; email: string; avatar_url: string | null }
const profileMap = Object.fromEntries(
  (profiles ?? []).map((p: ProfileRow) => [p.id, p]),
)

