// Check if email is already a member — fetch user_ids then lookup emails separately
const { data: existingMember } = await supabase
  .from('studio_members')
  .select('user_id')
  .eq('studio_id', authUser.studioId)
  .is('deactivated_at', null)

const memberUserIds = (existingMember ?? []).map((m) => m.user_id)
let emailAlreadyMember = false
if (memberUserIds.length > 0) {
  const { data: memberProfiles } = await supabase
    .from('profiles')
    .select('email')
    .in('id', memberUserIds)
  const emails = (memberProfiles ?? []).map((p) => p.email.toLowerCase().trim())
  emailAlreadyMember = emails.includes(body.data.email.toLowerCase().trim())
}
if (emailAlreadyMember) {
  return NextResponse.json({ error: 'already_a_member' }, { status: 409 })
}

